-- =============================================================================
-- 495 — LE CAHIER D'EXERCICES DE 3E (partie 9)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 495 --niveau 3e --fichiers allemand.n3,allemand.n4,anglais.jumelles,anglais.n1 --suffixe 9 > supabase/contenu/495_exercices_3e_9.sql
--
-- 99 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.n3             36 exercices · 12 chapitres
--   allemand.n4             27 exercices · 9 chapitres
--   anglais.jumelles         6 exercices · 2 chapitres
--   anglais.n1              30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un samedi chargé pour Lena","competence":"comprendre-langue","situation":"Mia veut voir Lena ce week-end. Lena lui répond par SMS et donne ses horaires : à toi de repérer comment elle dit le temps.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Samstag","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Lena","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Hast du am Samstag Zeit?"},{"qui":"Lena","texte":"Nur am Nachmittag. Um zehn Uhr habe ich Training."},{"qui":"Mia","texte":"Und im Juli? Fährst du weg?"},{"qui":"Lena","texte":"Ja, im Juli fahre ich zu meiner Oma."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui donne l’heure précise du Training.","aide":"C’est le petit mot placé juste devant « zehn Uhr ».","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces compléments de temps selon la préposition qui leur convient.","aide":"Jours et moments de la journée : am. Mois et saisons : im. Heures précises : um.","type":"categories","categories":[{"id":"c0","texte":"am"},{"id":"c1","texte":"im"},{"id":"c2","texte":"um"}],"items":[{"id":"i0","texte":"Mitternacht"},{"id":"i1","texte":"Januar"},{"id":"i2","texte":"Montag"},{"id":"i3","texte":"acht Uhr"},{"id":"i4","texte":"Sommer"},{"id":"i5","texte":"Abend"}]},{"enonce":"Lena propose : « Je suis libre le samedi après-midi. » Complète.","aide":"Samstagnachmittag est un moment précis d’un jour.","type":"trous","segments":["Ich habe ",0," Samstagnachmittag Zeit."],"banque":["im","am","in","um"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**um** s’emploie devant une heure précise : *um zehn Uhr*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c2","i4":"c1","i5":"c0"}},"explication":"**am** : jours et moments de la journée ; **im** : mois et saisons ; **um** : heure précise."},{"cle":{"type":"trous","trous":[["am"]]},"affichage":"am","explication":"**Ich habe am Samstagnachmittag Zeit.** *am* s’emploie pour les jours et les parties de la journée."}]$ex$::jsonb),
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre de Vienne","competence":"analyser-texte","situation":"Jonas passe quelques jours à Vienne et écrit à sa correspondante Paula. Son courrier est plein de repères de temps.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Liebe Paula","blocs":["Liebe Paula, vor zwei Wochen habe ich meine Reise geplant, und jetzt bin ich in Wien! Ich bleibe von Montag bis Freitag. Morgens gehe ich ins Museum, abends esse ich mit Freunden. In einer Woche bin ich wieder zu Hause. Bis bald! Jonas"],"source":"Courrier écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux petits mots qui disent « du lundi au vendredi ».","aide":"Cherche une préposition de départ et une préposition d’arrivée autour des jours.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche les deux adverbes qui disent ce que Jonas fait d’habitude, le matin et le soir.","aide":"Ils se terminent par un -s et décrivent une habitude.","type":"zone","document":"lettre","multiple":true},{"enonce":"Que dit Jonas dans « In einer Woche bin ich wieder zu Hause » ?","aide":"Pense au futur : *in* + datif exprime un moment à venir.","type":"choix","options":[{"id":"a","texte":"Il rentre pour une semaine"},{"id":"b","texte":"Il est rentré il y a une semaine"},{"id":"c","texte":"Il rentre dans une semaine"},{"id":"d","texte":"Il rentre depuis une semaine"}],"multiple":false},{"enonce":"Associe chaque expression de temps à sa traduction.","aide":"Vor = passé, in = futur, seit = depuis, während = pendant.","type":"association","gauche":[{"id":"g0","texte":"vor zwei Wochen"},{"id":"g1","texte":"in zwei Wochen"},{"id":"g2","texte":"seit zwei Wochen"},{"id":"g3","texte":"während der Ferien"}],"droite":[{"id":"d0","texte":"dans deux semaines"},{"id":"d1","texte":"il y a deux semaines"},{"id":"d2","texte":"depuis deux semaines"},{"id":"d3","texte":"pendant les vacances"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18","m20"]},"explication":"**von … bis** se traduit par « de … à » : *von Montag bis Freitag*."},{"cle":{"type":"zone","ids":["m22","m27"]},"explication":"**morgens** et **abends** (avec le -s) disent le matin et le soir « en général »."},{"cle":{"type":"choix","ids":["c"]},"explication":"**in einer Woche** = « dans une semaine » : on compte à partir de maintenant. Pour « il y a », on dirait *vor einer Woche*."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**vor** + datif : il y a ; **in** + datif : dans ; **seit** + datif : depuis ; **während** + génitif : pendant."}]$ex$::jsonb),
  ('69c4595a-9fe5-5a40-b550-9ebe8fb5cfec'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Échange scolaire à Hambourg","competence":"raisonner","situation":"Frau Brandt organise un échange entre Lyon et Hambourg. Elle affiche le programme, et pendant l’arrivée, une élève prévient son correspondant.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Schüleraustausch Lyon–Hamburg","sousTitre":"Programm","emoji":"🚆","lignes":[{"texte":"Ankunft","valeur":"am Montag, um 8 Uhr","id":"z1"},{"texte":"Dauer","valeur":"von Montag bis Freitag","id":"z2"},{"texte":"Sport","valeur":"jeden Nachmittag","id":"z3"},{"texte":"Pause","valeur":"während der Mittagszeit","id":"z4"},{"texte":"Abreise","valeur":"am Samstag","id":"z5"}],"pied":"Anmeldung bis morgen!","source":"Affiche écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Am Bahnhof","participants":[{"nom":"Lisa","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lisa","texte":"Wo seid ihr? Ich warte seit zehn Minuten am Bahnhof."},{"qui":"Max","texte":"Wir sind in fünf Minuten da."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la ligne dont le complément de temps est à l’accusatif, sans préposition.","aide":"Cherche une expression de temps qui commence par un déterminant et pas par une préposition.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui contient une préposition suivie du génitif.","aide":"Cette préposition veut dire « pendant ».","type":"zone","document":"affiche","multiple":false},{"enonce":"Frau Brandt écrit : « Lundi à huit heures, nous partons pour Hambourg. » Remets la phrase en ordre.","aide":"La phrase commence par le complément de temps : le verbe vient juste après, puis le sujet.","type":"ordre","items":[{"id":"a","texte":"fahren"},{"id":"b","texte":"wir"},{"id":"c","texte":"nach Hamburg"},{"id":"d","texte":"Am Montag um acht Uhr"}]},{"enonce":"Complète le programme : « L’échange dure du lundi au vendredi. »","aide":"Il faut une préposition de départ et une préposition d’arrivée.","type":"trous","segments":["Der Austausch dauert ",0," Montag ",1," Freitag."],"banque":["seit","von","ab","bis"]},{"enonce":"Touche la préposition qui dit que Lisa attend « depuis » dix minutes.","aide":"Cette préposition est suivie du datif et, en allemand, le verbe reste au présent.","type":"zone","document":"sms","multiple":false},{"enonce":"Que signifie « Wir sind in fünf Minuten da » ?","aide":"Pour parler de l’avenir, l’allemand dit *in* + datif.","type":"choix","options":[{"id":"a","texte":"Nous serons là dans cinq minutes"},{"id":"b","texte":"Nous sommes là pendant cinq minutes"},{"id":"c","texte":"Nous étions là il y a cinq minutes"},{"id":"d","texte":"Nous sommes là depuis cinq minutes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**jeden Nachmittag** est un accusatif sans préposition : une habitude qui se répète."},{"cle":{"type":"zone","ids":["z4"]},"explication":"**während** est suivie du génitif : *während der Mittagszeit*."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Am Montag um acht Uhr fahren wir nach Hamburg.** Le complément de temps ouvre la phrase : le verbe reste en deuxième position et le sujet passe derrière lui."},{"cle":{"type":"trous","trous":[["von"],["bis"]]},"affichage":"von · bis","explication":"**Der Austausch dauert von Montag bis Freitag.** *von … bis* = « de … à »."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**seit** = depuis ; avec elle, l’allemand garde le présent : *Ich warte seit zehn Minuten*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**in fünf Minuten** = « dans cinq minutes ». Le présent suffit pour l’avenir quand un complément de temps le précise."}]$ex$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un samedi chez Oma","competence":"comprendre-langue","situation":"Tom demande à Lea ce qu’elle a fait hier. Elle raconte, et Tom répond à son tour : repère les verbes qui portent le récit.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Was hast du gemacht?","participants":[{"nom":"Tom","emoji":"👧","cote":"gauche"},{"nom":"Lea","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Was hast du gestern gemacht?"},{"qui":"Lea","texte":"Ich war bei Oma. Ich bin mit dem Zug gefahren und habe Kuchen gebacken."},{"qui":"Tom","texte":"Ich habe Fußball gespielt."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes du verbe « sein » dans le message de Lea.","aide":"Cherche les mots qui veulent dire « étais » et « suis ».","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les trois formes de « haben » qui servent d’auxiliaire.","aide":"Elles sont devant un participe : gemacht, gebacken, gespielt.","type":"zone","document":"sms","multiple":true},{"enonce":"Range ces verbes selon l’auxiliaire qu’ils prennent au parfait.","aide":"Les verbes de déplacement d’un point à un autre prennent sein.","type":"categories","categories":[{"id":"c0","texte":"haben"},{"id":"c1","texte":"sein"}],"items":[{"id":"i0","texte":"essen"},{"id":"i1","texte":"spielen"},{"id":"i2","texte":"fliegen"},{"id":"i3","texte":"kommen"},{"id":"i4","texte":"machen"},{"id":"i5","texte":"fahren"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m10"]},"explication":"**war** (prétérit) et **bin** (présent) sont deux formes de *sein*."},{"cle":{"type":"zone","ids":["m1","m16","m20"]},"explication":"**hast**, **habe**, **habe** sont des formes de *haben* qui forment le parfait de *machen*, *backen* et *spielen*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"**sein** avec *fahren, kommen, fliegen* (déplacement) ; **haben** avec *spielen, essen, machen*."}]$ex$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un colis, un frère et un faux ami","competence":"analyser-texte","situation":"Une petite-fille remercie sa grand-mère dans une lettre. Attention : un mot ressemble à l’anglais « to become », mais il ne veut pas dire ce que tu crois.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Liebe Oma, danke für dein Paket! Ich habe es gestern bekommen. Mein Bruder wird bald Arzt. Er hat ein Stipendium bekommen. Ich bin müde geworden, weil wir viel gearbeitet haben. Bis bald!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux fois où le verbe « bekommen » apparaît.","aide":"C’est un participe II qui commence par be-.","type":"zone","document":"brief","multiple":true},{"enonce":"Que signifie « Ich habe es gestern bekommen » ?","aide":"*bekommen* a un sens très précis : ce n’est pas « devenir ».","type":"choix","options":[{"id":"a","texte":"Je suis devenu cela hier"},{"id":"b","texte":"Je l’ai donné hier"},{"id":"c","texte":"Je l’ai reçu hier"},{"id":"d","texte":"Je l’ai gardé hier"}],"multiple":false},{"enonce":"Complète : « Mon frère devient médecin. »","aide":"Pour dire « devenir », l’allemand emploie werden.","type":"trous","segments":["Mein Bruder ",0," Arzt."],"banque":["hat","wird","bekommt","ist"]},{"enonce":"Remets en ordre : « Je suis devenu fatigué. » La phrase commence par Ich.","aide":"Au parfait, l’auxiliaire est en deuxième position et le participe à la fin.","type":"ordre","items":[{"id":"a","texte":"Ich"},{"id":"b","texte":"müde"},{"id":"c","texte":"bin"},{"id":"d","texte":"geworden"}]},{"enonce":"Pourquoi dit-on « Ich bin müde geworden » et non « Ich habe müde geworden » ?","aide":"Souviens-toi des quatre verbes à part : sein, bleiben, werden, passieren.","type":"choix","options":[{"id":"a","texte":"bin est la forme polie de habe"},{"id":"b","texte":"müde est un verbe de déplacement"},{"id":"c","texte":"geworden est un verbe fort donc il prend sein"},{"id":"d","texte":"werden est l’un des quatre verbes à part avec sein"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m20"]},"explication":"**bekommen** apparaît deux fois : *Paket bekommen* et *Stipendium bekommen*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**bekommen** = « recevoir ». « Devenir » se dit *werden* : *Ich werde Arzt*."},{"cle":{"type":"trous","trous":[["wird"]]},"affichage":"wird","explication":"**Mein Bruder wird Arzt.** *werden* + nom = « devenir ». *bekommt* voudrait dire « reçoit »."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**Ich bin müde geworden.** *werden* forme son parfait avec *sein* : *bin … geworden*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**werden** fait partie des quatre verbes qui forment leur parfait avec *sein*, comme *sein*, *bleiben* et *passieren*."}]$ex$::jsonb),
  ('23b027cc-b04e-572e-b286-76f0ae9bd02d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Papa attend Nora","competence":"raisonner","situation":"Nora rentre en retard, et son père lui écrit. Puis un article local annonce la carrière d’un cuisinier. Dans les deux documents, des auxiliaires à ne pas confondre.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Wo bist du?","participants":[{"nom":"Papa","emoji":"👨","cote":"gauche"},{"nom":"Nora","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Wo bist du? Was ist passiert?"},{"qui":"Nora","texte":"Der Bus ist nicht gekommen. Ich bin zu Fuß gelaufen."},{"qui":"Papa","texte":"Du hast bestimmt Hunger. Ich habe Pizza gemacht."},{"qui":"Nora","texte":"Super! Ich bin gleich da."}],"source":"Messages écrits pour l’exercice"},{"id":"presse","type":"texte","genre":"article","titre":"Neues aus dem Viertel","blocs":["Mein Bruder wird Koch. Er wird bald in Berlin arbeiten. Das Restaurant wird gerade gebaut."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois « sein » qui servent d’auxiliaire au parfait.","aide":"Chacun est suivi d’un participe : passiert, gekommen, gelaufen.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche le seul « haben » qui sert ici d’auxiliaire.","aide":"L’autre « hast » est suivi d’un nom : Hunger.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Nora dit-elle « Ich bin zu Fuß gelaufen » ?","aide":"Demande-toi si Nora va d’un endroit à un autre.","type":"choix","options":[{"id":"a","texte":"laufen est un verbe qui change de voyelle"},{"id":"b","texte":"zu Fuß exige toujours le verbe sein"},{"id":"c","texte":"Parce que le sujet est ich"},{"id":"d","texte":"laufen est un déplacement d’un point à un autre"}],"multiple":false},{"enonce":"Range ces phrases selon l’auxiliaire du parfait.","aide":"Un verbe de mouvement avec un COD prend haben.","type":"categories","categories":[{"id":"c0","texte":"haben"},{"id":"c1","texte":"sein"}],"items":[{"id":"i0","texte":"Ich … nach Köln gefahren"},{"id":"i1","texte":"Ich … das Auto gefahren (j’ai conduit la voiture)"},{"id":"i2","texte":"Er … eingeschlafen"},{"id":"i3","texte":"Wir … Fußball gespielt"},{"id":"i4","texte":"Es … schon passiert"},{"id":"i5","texte":"Sie … einen Brief geschrieben"}]},{"enonce":"Associe chaque phrase de l’article à sa traduction.","aide":"Regarde ce qui suit werden : un nom, un infinitif ou un participe.","type":"association","gauche":[{"id":"g0","texte":"Er wird Koch"},{"id":"g1","texte":"Er wird arbeiten"},{"id":"g2","texte":"Das Restaurant wird gebaut"}],"droite":[{"id":"d0","texte":"Il devient cuisinier"},{"id":"d1","texte":"Le restaurant est construit"},{"id":"d2","texte":"Il travaillera"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m8","m12"]},"explication":"**ist** (… passiert), **ist** (… gekommen) et **bin** (… gelaufen) sont des auxiliaires. Les autres « bist » et « bin » sont des verbes pleins."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**habe** forme le parfait de *machen*. *Du hast Hunger* utilise *haben* comme verbe plein (« avoir faim »)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**sein** s’emploie avec les verbes de déplacement d’un point à un autre : *Ich bin gelaufen*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**haben** quand il y a un COD (*das Auto gefahren*) ou pour la plupart des verbes ; **sein** pour le déplacement (*nach Köln gefahren*) et le changement d’état (*eingeschlafen*, *passiert*)."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**werden** + nom = devenir ; + infinitif = futur ; + participe II = passif."}]$ex$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le tableau des trois formes","competence":"lire-tableau","situation":"Un camarade a commencé à recopier les trois formes de quatre verbes. Observe le tableau et complète ce qui manque.","documents":[{"id":"tab","type":"tableau","titre":"Trois temps primitifs","colonnes":["Infinitif","Prétérit","Participe II"],"lignes":[["machen","machte","gemacht"],["spielen","spielte","?"],["fahren","fuhr","gefahren"],["nehmen","nahm","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux prétérits en -te : ce sont des verbes faibles.","aide":"Le prétérit d’un verbe faible se termine par -te.","type":"zone","document":"tab","multiple":true},{"enonce":"Quel est le participe II de « spielen » ?","aide":"Verbe faible : ge- + radical + -t.","type":"texte"},{"enonce":"Quel est le participe II de « nehmen » ?","aide":"Verbe fort : ge- + radical modifié + -en.","type":"texte"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r1c1"]},"explication":"**machte** et **spielte** se terminent par -te : *machen* et *spielen* sont faibles."},{"cle":{"type":"texte","acceptes":["gespielt"]},"affichage":"gespielt","explication":"**gespielt** : *ge-* + *spiel* + *-t*."},{"cle":{"type":"texte","acceptes":["genommen"]},"affichage":"genommen","explication":"**genommen** : *ge-* + *nomm* (la voyelle a changé) + *-en*."}]$ex$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le voyage de Lukas","competence":"manier-langue","situation":"Sophie et Max parlent du voyage de Lukas à Bonn. Plusieurs verbes forts changent de voyelle : saurais-tu les reconnaître ?","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Lukas fährt nach Bonn","participants":[{"nom":"Sophie","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sophie","texte":"Was macht Lukas? Er fährt heute nach Bonn, oder?"},{"qui":"Max","texte":"Ja, er fährt mit dem Zug. Er liest ein Buch und er schläft ein bisschen."},{"qui":"Sophie","texte":"Und du? Du gibst ihm das Ticket?"},{"qui":"Max","texte":"Ja, ich gebe ihm das Ticket. Wir fahren zusammen zum Bahnhof."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les formes de la 3e personne du singulier dont la voyelle a changé par rapport à l’infinitif.","aide":"Cherche les ä et le ie : fahren, lesen, schlafen.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec « nehmen » : « Lukas prend le train et toi tu prends le bus. »","aide":"Avec nehmen, la voyelle e devient i aux 2e et 3e personnes du singulier.","type":"trous","segments":["Lukas ",0," den Zug und du ",1," den Bus."],"banque":["nehmt","nimmst","nehme","nimmt"]},{"enonce":"Range ces verbes selon le changement de voyelle à la 2e personne du singulier.","aide":"Compare la voyelle de l’infinitif avec celle de la forme entre parenthèses.","type":"categories","categories":[{"id":"c0","texte":"e → i"},{"id":"c1","texte":"e → ie"},{"id":"c2","texte":"a → ä"}],"items":[{"id":"i0","texte":"fahren (du fährst)"},{"id":"i1","texte":"sprechen (du sprichst)"},{"id":"i2","texte":"lesen (du liest)"},{"id":"i3","texte":"schlafen (du schläfst)"},{"id":"i4","texte":"geben (du gibst)"},{"id":"i5","texte":"sehen (du siehst)"}]},{"enonce":"Pourquoi Max dit-il « Wir fahren » avec un a et non « Wir fähren » ?","aide":"Regarde les formes du pluriel dans le message : fahren, geben…","type":"choix","options":[{"id":"a","texte":"Le ä n’existe pas dans le nord de l’Allemagne"},{"id":"b","texte":"fahren est un verbe faible au pluriel"},{"id":"c","texte":"Wir est une forme de politesse"},{"id":"d","texte":"L’alternance ne touche que du et er/sie/es"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m11","m16","m21"]},"explication":"**fährt** (a → ä), **liest** (e → ie), **schläft** (a → ä) : la voyelle change à la 3e personne du singulier."},{"cle":{"type":"trous","trous":[["nimmt"],["nimmst"]]},"affichage":"nimmt · nimmst","explication":"**Lukas nimmt den Zug und du nimmst den Bus.** *nehmen* : e → i, avec *-t* pour *er* et *-st* pour *du*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c2","i4":"c0","i5":"c1"}},"explication":"**e → i** : *sprechen, geben* ; **e → ie** : *sehen, lesen* ; **a → ä** : *fahren, schlafen*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**wir fahren** : l’alternance a → ä n’existe qu’à *du* et *er/sie/es* ; elle disparaît au pluriel."}]$ex$::jsonb),
  ('a9623262-cdfd-5fed-9dfe-c6df75188108'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le compte rendu de la visite","competence":"analyser-texte","situation":"Un élève raconte sa visite chez Marie. Son texte cache des participes de tous les types : forts, mixtes, en -ieren. Un second document propose de compléter un tableau.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Bei Marie","blocs":["Gestern habe ich Marie besucht. Wir haben lange gesprochen. Sie hat mir ein Buch gebracht, und ich habe ihr einen Brief geschrieben. Ihr Bruder hat in Lyon studiert. Er hat auch mit uns telefoniert."],"source":"Texte écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"À toi de jouer","colonnes":["Infinitif","Prétérit","Participe II"],"lignes":[["denken","dachte","?"],["essen","aß","?"],["googeln","googelte","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes de verbes forts (ils se terminent par -en).","aide":"Cherche ge- … -en avec une voyelle modifiée.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche les deux participes qui n’ont pas de « ge- » : ce sont des verbes en -ieren.","aide":"Ils se terminent par -iert.","type":"zone","document":"recit","multiple":true},{"enonce":"Touche le participe d’un verbe mixte : radical modifié et terminaison faible.","aide":"Il se termine par -t, mais le radical n’est plus celui de l’infinitif (bringen).","type":"zone","document":"recit","multiple":false},{"enonce":"Complète les participes II du tableau.","aide":"Mixte : ge- + radical modifié + -t. Fort : ge- … -en. Faible : ge- … -t.","type":"trous","segments":["denken → ",0," · essen → ",1," · googeln → ",2]},{"enonce":"Pourquoi le participe de « besuchen » est-il « besucht » et non « gebesucht » ?","aide":"Regarde le début du verbe : be-.","type":"choix","options":[{"id":"a","texte":"Le participe se forme ici avec sein et non haben"},{"id":"b","texte":"be- est un préverbe inséparable : pas de ge-"},{"id":"c","texte":"besuchen se termine par -ieren comme studieren"},{"id":"d","texte":"besuchen est un verbe fort qui change de voyelle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m21"]},"explication":"**gesprochen** (*sprechen*) et **geschrieben** (*schreiben*) sont des participes forts."},{"cle":{"type":"zone","ids":["m27","m33"]},"explication":"**studiert** et **telefoniert** viennent de *studieren* et *telefonieren* : les verbes en -ieren sont faibles et sans ge-."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**gebracht** : *bringen* est mixte, le radical change (*brach-*) mais la terminaison est faible (*-t*)."},{"cle":{"type":"trous","trous":[["gedacht"],["gegessen"],["gegoogelt"]]},"affichage":"gedacht · gegessen · gegoogelt","explication":"**gedacht** (mixte), **gegessen** (fort), **gegoogelt** (faible, comme tout verbe nouveau)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**besucht** : les préverbes inséparables (*be-, ver-, er-*…) refusent le *ge-*."}]$ex$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les règles de la piscine","competence":"comprendre-langue","situation":"À l’entrée de la piscine municipale, une affiche rappelle les règles. Chaque ligne emploie un verbe de modalité différent.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Schwimmbad","sousTitre":"Die Regeln","emoji":"🏊","lignes":[{"texte":"Du musst vor dem Schwimmen duschen.","id":"z1"},{"texte":"Du darfst nicht rennen.","id":"z2"},{"texte":"Du kannst im Kiosk ein Eis kaufen.","id":"z3"},{"texte":"Du sollst bei Gewitter aus dem Wasser kommen.","id":"z4"}],"pied":"Viel Spaß!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui exprime une interdiction.","aide":"Cherche le modal qui parle du droit, avec nicht.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui dit simplement ce qu’on est capable ou en mesure de faire.","aide":"C’est le modal de la possibilité, de la capacité.","type":"zone","document":"affiche","multiple":false},{"enonce":"Associe chaque modal à son idée principale.","aide":"Pense à ce que chaque modal exprime : capacité, droit, nécessité, volonté.","type":"association","gauche":[{"id":"g0","texte":"können"},{"id":"g1","texte":"dürfen"},{"id":"g2","texte":"müssen"},{"id":"g3","texte":"wollen"}],"droite":[{"id":"d0","texte":"devoir (nécessité)"},{"id":"d1","texte":"avoir le droit"},{"id":"d2","texte":"pouvoir (capacité)"},{"id":"d3","texte":"vouloir (volonté ferme)"}]},{"enonce":"Remets en ordre : « Je veux nager aujourd’hui. » La phrase commence par Ich.","aide":"Le modal est en deuxième position, l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"Ich"},{"id":"b","texte":"heute"},{"id":"c","texte":"will"},{"id":"d","texte":"schwimmen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Du darfst nicht rennen** : *dürfen* + *nicht* dit l’interdiction (« tu n’as pas le droit »)."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Du kannst im Kiosk ein Eis kaufen** : *können* exprime la possibilité."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**können** : capacité ; **dürfen** : droit ; **müssen** : nécessité ; **wollen** : volonté ferme."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**Ich will heute schwimmen.** Le modal conjugué est en 2e position, l’infinitif à la fin de la phrase."}]$ex$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pas obligé ou pas le droit ?","competence":"comprendre-langue","situation":"Nils discute avec son père avant le week-end. Entre « pas obligé » et « interdit », un seul mot change tout.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Das Wochenende","participants":[{"nom":"Papa","emoji":"👨","cote":"gauche"},{"nom":"Nils","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Du musst heute nicht aufräumen. Aber du darfst nicht so lange fernsehen."},{"qui":"Nils","texte":"Ich muss nicht aufräumen? Super! Ich will mit Ben ins Kino gehen."},{"qui":"Papa","texte":"Du kannst gehen. Aber du sollst um zehn Uhr zu Hause sein, sagt Mama."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui, avec « nicht », exprime une interdiction.","aide":"C’est le modal du droit.","type":"zone","document":"sms","multiple":false},{"enonce":"Que signifie « Du musst heute nicht aufräumen » ?","aide":"Müssen + nicht nie veut dire « interdit ».","type":"choix","options":[{"id":"a","texte":"Tu n’es pas obligé de ranger"},{"id":"b","texte":"Tu n’as pas le droit de ranger"},{"id":"c","texte":"Tu ne peux pas ranger"},{"id":"d","texte":"Tu dois ranger deux fois"}],"multiple":false},{"enonce":"Touche le modal qui rapporte une consigne venue de Mama.","aide":"Il exprime un ordre qui vient d’une autre personne.","type":"zone","document":"sms","multiple":false},{"enonce":"Remets en ordre : « Il reste à la maison parce qu’il doit travailler. » La phrase commence par Er bleibt zu Hause.","aide":"Après weil, tout part à la fin : l’infinitif, puis le modal conjugué.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"arbeiten"},{"id":"c","texte":"er"},{"id":"d","texte":"muss"},{"id":"e","texte":"Er bleibt zu Hause"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**darfst … nicht** : « tu n’as pas le droit de ». Une interdiction, et non une absence d’obligation."},{"cle":{"type":"choix","ids":["a"]},"explication":"**müssen + nicht** = « ne pas être obligé » : l’action est facultative, pas interdite."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**sollst** : *sollen* rapporte une consigne extérieure (« on t’a dit de… »)."},{"cle":{"type":"ordre","ids":["e","a","c","b","d"]},"explication":"**Er bleibt zu Hause, weil er arbeiten muss.** Dans la subordonnée, le verbe conjugué (le modal) est tout à la fin."}]$ex$::jsonb),
  ('cad5c6bf-e3a1-5759-a79e-8ac9b48b24b2'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Une excuse et une invitation","competence":"raisonner","situation":"Emma s’excuse auprès de Clara pour une fête manquée. Clara lui envoie alors une nouvelle invitation. Deux documents, six modaux à bien comprendre.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Liebe Clara","blocs":["Liebe Clara, es tut mir leid: Ich habe gestern nicht zu deiner Party kommen können. Ich musste für Mathe lernen, weil wir heute eine Arbeit schreiben müssen. Mama sagt, ich soll früh schlafen. Nächste Woche will ich dich besuchen. Dann darf ich auch länger bleiben. Deine Emma"],"source":"Lettre écrite pour l’exercice"},{"id":"invit","type":"fiche","modele":"invitation","entete":"Clara lädt dich ein","sousTitre":"Party am Samstag","emoji":"🎉","lignes":[{"texte":"Du kannst kommen!","id":"z1"},{"texte":"Du darfst Freunde mitbringen.","id":"z2"},{"texte":"Du musst nichts mitbringen.","id":"z3"}],"pied":"Ich freue mich auf dich!","source":"Invitation écrite pour l’exercice"}],"questions":[{"enonce":"Touche le modal conjugué au prétérit.","aide":"Le prétérit de müssen se termine par -te.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche les deux verbes qui forment le « double infinitif » du parfait.","aide":"À la fin de la phrase, le participe est remplacé par deux infinitifs.","type":"zone","document":"lettre","multiple":true},{"enonce":"Remets en ordre : « … parce que nous devons écrire un devoir. » La phrase commence par weil.","aide":"Dans la subordonnée, l’infinitif puis le modal conjugué sont tout à la fin.","type":"ordre","items":[{"id":"a","texte":"eine Arbeit"},{"id":"b","texte":"schreiben"},{"id":"c","texte":"müssen"},{"id":"d","texte":"weil"},{"id":"e","texte":"wir"}]},{"enonce":"Complète au parfait : « Hier, je n’ai pas pu venir. »","aide":"Avec un infinitif dépendant, le modal ne prend pas de participe.","type":"trous","segments":["Ich habe gestern nicht kommen ",0,"."],"banque":["konnte","gekonnt","können","kann"]},{"enonce":"Touche la ligne qui donne une autorisation.","aide":"Cherche le modal du droit.","type":"zone","document":"invit","multiple":false},{"enonce":"Que signifie « Du musst nichts mitbringen » ?","aide":"Müssen + négation ne dit pas l’interdiction.","type":"choix","options":[{"id":"a","texte":"Tu n’as pas le droit d’apporter quoi que ce soit"},{"id":"b","texte":"Tu ne sais pas apporter quoi que ce soit"},{"id":"c","texte":"Tu n’es pas obligé d’apporter quoi que ce soit"},{"id":"d","texte":"Tu dois tout apporter"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**musste** est le prétérit de *müssen* : sans inflexion, avec la terminaison *-te*."},{"cle":{"type":"zone","ids":["m13","m14"]},"explication":"**kommen können** : au parfait, un modal suivi d’un infinitif ne prend pas de participe. C’est le « double infinitif »."},{"cle":{"type":"ordre","ids":["d","e","a","b","c"]},"explication":"**weil wir eine Arbeit schreiben müssen.** Le modal conjugué ferme la subordonnée."},{"cle":{"type":"trous","trous":[["konnen"]]},"affichage":"können","explication":"**Ich habe gestern nicht kommen können.** Double infinitif : l’infinitif du modal (*können*) à la toute fin."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Du darfst Freunde mitbringen** : *dürfen* donne l’autorisation (« tu as le droit de »)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**müssen + nichts** : aucune obligation. Clara dit à son invitée qu’elle peut venir les mains vides."}]$ex$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le matin de Leo","competence":"comprendre-langue","situation":"Leo raconte sa matinée. Dans son récit, quatre petits mots sont partis à la fin de leur phrase : les préverbes séparables.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Ein Morgen","blocs":["Leo steht um sieben Uhr auf. Er isst ein Brot und ruft Tom an. Dann geht er mit Tom zum Bus. Um acht Uhr kommt er in der Schule an. Mittags kauft er in der Pause ein."],"source":"Récit écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre préverbes séparés qui ferment leur phrase.","aide":"Ils sont tout seuls à la fin : ils étaient collés au verbe à l’infinitif.","type":"zone","document":"recit","multiple":true},{"enonce":"Associe chaque verbe de Leo à son sens.","aide":"Reconstitue le verbe : préverbe + radical.","type":"association","gauche":[{"id":"g0","texte":"aufstehen"},{"id":"g1","texte":"anrufen"},{"id":"g2","texte":"ankommen"},{"id":"g3","texte":"einkaufen"}],"droite":[{"id":"d0","texte":"se lever"},{"id":"d1","texte":"téléphoner à"},{"id":"d2","texte":"faire les courses"},{"id":"d3","texte":"arriver"}]},{"enonce":"Remets en ordre : « Il se lève à sept heures. » La phrase commence par Er.","aide":"Le verbe est en 2e position, le préverbe tout à la fin.","type":"ordre","items":[{"id":"a","texte":"auf"},{"id":"b","texte":"um sieben Uhr"},{"id":"c","texte":"steht"},{"id":"d","texte":"Er"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m13","m29","m36"]},"explication":"**auf, an, an, ein** : dans une principale, le préverbe quitte le verbe et va en fin de phrase."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**aufstehen** (se lever), **anrufen** (appeler), **ankommen** (arriver), **einkaufen** (faire les courses)."},{"cle":{"type":"ordre","ids":["d","c","b","a"]},"explication":"**Er steht um sieben Uhr auf.** Le verbe conjugué est en 2e position, le préverbe ferme la phrase."}]$ex$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un week-end en famille","competence":"manier-langue","situation":"Tom raconte son week-end à Lea. Au parfait, certains participes ont un ge- au milieu, d’autres n’en ont pas du tout.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Das Wochenende","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"Was hast du am Wochenende gemacht?"},{"qui":"Tom","texte":"Ich habe Fußball gespielt und meine Großeltern besucht. Ich habe auch ein neues Gericht probiert."},{"qui":"Lea","texte":"Hast du etwas mitgebracht?"},{"qui":"Tom","texte":"Ja, Kuchen. Und ich bin früh eingeschlafen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui n’ont pas de ge-.","aide":"L’un commence par un préverbe inséparable (be-), l’autre vient d’un verbe en -ieren.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les deux participes où le ge- s’est glissé entre le préverbe et le radical.","aide":"Ce sont des verbes séparables : mit- et ein-.","type":"zone","document":"sms","multiple":true},{"enonce":"Écris les participes II.","aide":"Séparable : ge- au milieu. En -ieren et inséparable : pas de ge-.","type":"trous","segments":["aufräumen → ",0," · kopieren → ",1," · vergessen → ",2]},{"enonce":"Pourquoi Tom dit-il « Ich bin früh eingeschlafen » avec « bin » ?","aide":"Passer de l’éveil au sommeil, c’est changer d’état.","type":"choix","options":[{"id":"a","texte":"einschlafen exprime un changement d’état"},{"id":"b","texte":"Tom parle de lui-même"},{"id":"c","texte":"Tous les verbes séparables prennent sein"},{"id":"d","texte":"ein- est un préverbe inséparable"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m20"]},"explication":"**besucht** (préverbe inséparable *be-*) et **probiert** (verbe en *-ieren*) n’ont pas de ge-."},{"cle":{"type":"zone","ids":["m24","m31"]},"explication":"**mitgebracht** et **eingeschlafen** : le ge- s’intercale entre le préverbe séparable et le radical."},{"cle":{"type":"trous","trous":[["aufgeraumt"],["kopiert"],["vergessen"]]},"affichage":"aufgeräumt · kopiert · vergessen","explication":"**aufgeräumt** (ge- intercalé), **kopiert** (-ieren, sans ge-), **vergessen** (préverbe ver- inséparable, sans ge-)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**einschlafen** exprime un changement d’état : au parfait, il prend **sein**."}]$ex$::jsonb),
  ('162e7a35-e97d-546e-bef9-b6784356df19'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Je t’appelle quand tu arrives","competence":"raisonner","situation":"Eva et Ben s’organisent par SMS. Plusieurs verbes y sont séparables, un autre refuse de se séparer, et l’un d’eux se recolle dans une subordonnée.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Pläne","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Kommst du heute mit?"},{"qui":"Eva","texte":"Ich rufe dich an, wenn mein Zug ankommt."},{"qui":"Ben","texte":"Okay. Ich habe dein Paket bekommen."},{"qui":"Eva","texte":"Super! Ich hole es morgen ab."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois préverbes détachés, tout seuls à la fin de leur phrase.","aide":"Ils sont séparés de leur verbe : mitkommen, anrufen, abholen.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche le verbe qui s’est « recollé » parce qu’il est dans une subordonnée.","aide":"Il est après « wenn » et son préverbe est revenu devant lui.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le participe qui n’a pas de ge- parce que son préverbe est inséparable.","aide":"Il commence par be-.","type":"zone","document":"sms","multiple":false},{"enonce":"Remets en ordre : « Je t’appelle quand il arrive. » La phrase commence par Ich.","aide":"La principale se termine par le préverbe ; la subordonnée recolle le verbe à la fin.","type":"ordre","items":[{"id":"a","texte":"dich"},{"id":"b","texte":"rufe"},{"id":"c","texte":"ankommt"},{"id":"d","texte":"er"},{"id":"e","texte":"Ich"},{"id":"f","texte":"wenn"},{"id":"g","texte":"an"}]},{"enonce":"Complète avec zu : « Je n’ai pas envie de me lever tôt, ni le temps de rendre visite à Oma. »","aide":"Séparable : zu s’intercale. Inséparable : zu reste devant.","type":"trous","segments":["Ich habe keine Lust, früh ",0," (aufstehen), und keine Zeit, Oma ",1," (besuchen)."]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m7","m23"]},"explication":"**mit, an, ab** : dans une principale, le préverbe séparable va à la fin."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**ankommt** : en subordonnée, le verbe conjugué part à la fin et rejoint son préverbe."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**bekommen** : *be-* est inséparable, donc pas de *ge-* (et le verbe veut dire « recevoir »)."},{"cle":{"type":"ordre","ids":["e","b","a","g","f","d","c"]},"explication":"**Ich rufe dich an, wenn er ankommt.** Principale : préverbe séparé à la fin ; subordonnée : *ankommt* recollé et en dernière position."},{"cle":{"type":"trous","trous":[["aufzustehen"],["zu besuchen"]]},"affichage":"aufzustehen · zu besuchen","explication":"**aufzustehen** (le *zu* s’intercale) et **zu besuchen** (*be-* est inséparable : *zu* reste devant)."}]$ex$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les vacances approchent","competence":"comprendre-langue","situation":"Lina et Tom discutent des vacances. Dans leurs messages, on retrouve le pronom réfléchi : mich, dich, sich…","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Ferien","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Ich freue mich auf die Ferien!"},{"qui":"Tom","texte":"Ich auch! Ich interessiere mich für Sport. Und du?"},{"qui":"Lina","texte":"Ich wasche mich schnell, dann kommen wir."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois pronoms réfléchis de la 1re personne.","aide":"Ils sont juste après le verbe : freue, interessiere, wasche.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche la préposition qui accompagne « sich freuen » pour se réjouir de ce qui vient.","aide":"Elle est suivie de l’accusatif et parle de l’avenir.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète : « Nous nous agaçons du mauvais temps. »","aide":"Sich ärgern se construit avec une préposition suivie de l’accusatif.","type":"trous","segments":["Wir ärgern uns ",0," das schlechte Wetter."],"banque":["auf","an","über","für"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m10","m17"]},"explication":"**mich** apparaît trois fois : accusatif du réfléchi à la 1re personne du singulier."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**sich freuen auf** + accusatif : se réjouir d’un événement à venir."},{"cle":{"type":"trous","trous":[["uber"]]},"affichage":"über","explication":"**Wir ärgern uns über das schlechte Wetter.** *sich ärgern über* + accusatif."}]$ex$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mich ou mir ?","competence":"manier-langue","situation":"Après le sport, une élève raconte sa soirée. Selon la phrase, le pronom réfléchi est à l’accusatif ou au datif.","documents":[{"id":"journal","type":"texte","genre":"recit","titre":"Nach dem Sport","blocs":["Nach dem Sport wasche ich mich. Dann putze ich mir die Zähne und kaufe mir ein Eis. Ich sehe mir einen Film an, und ich freue mich auf das Wochenende."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois pronoms réfléchis au datif.","aide":"Ils s’écrivent mir et apparaissent quand la phrase a déjà un COD.","type":"zone","document":"journal","multiple":true},{"enonce":"Touche les deux pronoms réfléchis à l’accusatif.","aide":"Ils s’écrivent mich et il n’y a pas de COD dans leur phrase.","type":"zone","document":"journal","multiple":true},{"enonce":"Pourquoi dit-on « Ich kaufe mir ein Eis » et non « Ich kaufe mich ein Eis » ?","aide":"Cherche le COD dans la phrase.","type":"choix","options":[{"id":"a","texte":"kaufen est un verbe pronominal à l’accusatif"},{"id":"b","texte":"La phrase contient déjà un COD : ein Eis"},{"id":"c","texte":"mir est la forme de politesse"},{"id":"d","texte":"ein Eis est un complément de temps"}],"multiple":false},{"enonce":"Complète avec le bon pronom.","aide":"À la 3e personne, le datif et l’accusatif sont identiques.","type":"trous","segments":["Max kauft ",0," ein Buch, und wir freuen ",1," auf Samstag."],"banque":["euch","dir","dich","sich","uns"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m14","m19"]},"explication":"**mir** (3 fois) : au datif, parce que *die Zähne*, *ein Eis* et *einen Film* sont déjà des COD."},{"cle":{"type":"zone","ids":["m5","m26"]},"explication":"**mich** (2 fois) : à l’accusatif, car ni *wasche* ni *freue … auf* n’ont de COD."},{"cle":{"type":"choix","ids":["b"]},"explication":"Dès qu’il y a un COD (*ein Eis*), le réfléchi passe au **datif** : *mir*."},{"cle":{"type":"trous","trous":[["sich"],["uns"]]},"affichage":"sich · uns","explication":"**Max kauft sich ein Buch, und wir freuen uns auf Samstag.** *sich* (3e personne, datif) et *uns* (1re personne du pluriel)."}]$ex$::jsonb),
  ('0a3658f3-c285-528d-b4cb-fcc46efab45e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre pour Oma","competence":"argumenter","situation":"Une élève écrit à sa grand-mère. Elle se réjouit, s’agace, s’intéresse… et chaque verbe pronominal a sa préposition.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Liebe Oma, ich freue mich sehr auf deinen Besuch im Sommer. Mein Bruder hat sich leider verspätet, deshalb ärgere ich mich über ihn. Interessierst du dich noch für Gartenarbeit? Erinnerst du dich an Opas Geburtstag? Ich möchte mir ein neues Fahrrad kaufen."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le pronom réfléchi de la 3e personne (« mon frère s’est… »).","aide":"Il s’écrit avec un s et ne change pas entre accusatif et datif.","type":"zone","document":"brief","multiple":false},{"enonce":"Touche la préposition qui accompagne « freue mich » quand on attend la visite.","aide":"Elle parle de ce qui va venir.","type":"zone","document":"brief","multiple":false},{"enonce":"Associe chaque verbe pronominal à sa préposition.","aide":"Le sens (ce qui vient ou ce qui est arrivé) distingue les deux sich freuen.","type":"association","gauche":[{"id":"g0","texte":"sich freuen (ce qui vient)"},{"id":"g1","texte":"sich freuen (ce qui est arrivé)"},{"id":"g2","texte":"sich interessieren"},{"id":"g3","texte":"sich erinnern"}],"droite":[{"id":"d0","texte":"an"},{"id":"d1","texte":"über"},{"id":"d2","texte":"auf"},{"id":"d3","texte":"für"}]},{"enonce":"Range ces verbes : pronominal en allemand ou non ?","aide":"Aufstehen, heißen et spazieren gehen sont pronominaux en français seulement.","type":"categories","categories":[{"id":"c0","texte":"Pronominal en allemand"},{"id":"c1","texte":"Pas pronominal en allemand"}],"items":[{"id":"i0","texte":"heißen"},{"id":"i1","texte":"aufstehen"},{"id":"i2","texte":"sich verspäten"},{"id":"i3","texte":"sich interessieren"},{"id":"i4","texte":"sich freuen"},{"id":"i5","texte":"spazieren gehen"}]},{"enonce":"Remets en ordre : « Je souris parce que je me réjouis. » La phrase commence par Ich lächle.","aide":"En subordonnée, le pronom réfléchi suit le sujet, et le verbe est à la fin.","type":"ordre","items":[{"id":"a","texte":"weil"},{"id":"b","texte":"ich"},{"id":"c","texte":"mich"},{"id":"d","texte":"Ich lächle"},{"id":"e","texte":"freue"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**sich** est le réfléchi de la 3e personne du singulier : *Mein Bruder hat sich verspätet*."},{"cle":{"type":"zone","ids":["m6"]},"explication":"**sich freuen auf** : se réjouir de ce qui vient. Pour ce qui est arrivé, on dit *sich freuen über*."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**auf** (ce qui vient), **über** (ce qui est arrivé), **für** (s’intéresser à), **an** (se souvenir de) : toutes avec l’accusatif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"*aufstehen* (se lever), *heißen* (s’appeler) et *spazieren gehen* (se promener) n’ont **pas** de pronom en allemand ; *sich verspäten* en a un alors que le français dit « être en retard »."},{"cle":{"type":"ordre","ids":["d","a","b","c","e"]},"explication":"**Ich lächle, weil ich mich freue.** Dans la subordonnée, le réfléchi vient après le sujet et le verbe conjugué ferme la phrase."}]$ex$::jsonb),
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que fais-tu aujourd’hui ?","competence":"comprendre-langue","situation":"Nina et Jan se demandent ce qu’ils font aujourd’hui. Repère les terminaisons du présent.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Heute","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Jan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Was machst du heute?"},{"qui":"Jan","texte":"Ich spiele Fußball. Und du?"},{"qui":"Nina","texte":"Ich lerne. Mein Bruder spielt auch."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes conjugués à la 1re personne du singulier.","aide":"Ils se terminent par -e et suivent « Ich ».","type":"zone","document":"sms","multiple":true},{"enonce":"Touche la forme conjuguée à la 2e personne du singulier.","aide":"Elle se termine par -st.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète : « Tu apprends beaucoup et nous jouons ensemble. »","aide":"Du : terminaison -st. Wir : terminaison -en.","type":"trous","segments":["Du ",0," viel, und wir ",1," zusammen."],"banque":["spielen","spielt","lernt","lernst"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m10"]},"explication":"**spiele** et **lerne** : à *ich*, la terminaison du présent est **-e**."},{"cle":{"type":"zone","ids":["m1"]},"explication":"**machst** : à *du*, la terminaison est **-st**."},{"cle":{"type":"trous","trous":[["lernst"],["spielen"]]},"affichage":"lernst · spielen","explication":"**Du lernst viel, und wir spielen zusammen.** *du* → *-st* ; *wir* → *-en*."}]$ex$::jsonb),
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le carnet de conjugaison","competence":"lire-tableau","situation":"Un élève prépare sa fiche de conjugaison. Il a laissé deux cases vides : à toi de voir quelle règle de prononciation s’applique.","documents":[{"id":"tab","type":"tableau","titre":"Présent : ich et du","colonnes":["Verbe","ich","du"],"lignes":[["arbeiten","arbeite","arbeitest"],["heißen","heiße","heißt"],["sammeln","sammle","sammelst"],["finden","finde","?"],["sitzen","sitze","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case où le e du radical tombe à la 1re personne.","aide":"Cherche un verbe en -eln.","type":"zone","document":"tab","multiple":false},{"enonce":"Complète la case : « du » + finden.","aide":"Le radical se termine par -d : on intercale un e.","type":"texte"},{"enonce":"Complète la case : « du » + sitzen.","aide":"Le radical se termine par -z : le -st perd son s.","type":"texte"},{"enonce":"Pourquoi écrit-on « du heißt » et non « du heißst » ?","aide":"Regarde la lettre qui précède la terminaison -st.","type":"choix","options":[{"id":"a","texte":"Après ß, le -st perd son s"},{"id":"b","texte":"ß est une consonne muette"},{"id":"c","texte":"Après ß on ajoute un e"},{"id":"d","texte":"heißen est un verbe fort"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**sammle** : avec les verbes en *-eln*, le *e* du radical tombe à *ich*."},{"cle":{"type":"texte","acceptes":["findest"]},"affichage":"findest","explication":"**findest** : après -d ou -t, on glisse un *e* pour pouvoir prononcer *-st* (comme *du arbeitest*)."},{"cle":{"type":"texte","acceptes":["sitzt"]},"affichage":"sitzt","explication":"**sitzt** : après -s, -ß, -z, -x, la terminaison *-st* perd son *s* (comme *du heißt*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**du heißt** : quand le radical finit par -s, -ß, -z ou -x, le *s* de *-st* disparaît."}]$ex$::jsonb),
  ('4b75b12e-6b58-576e-8a78-c2843ce7bf9e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Depuis trois ans à Berlin","competence":"raisonner","situation":"Paul veut aller à Berlin et interroge Mia, qui y habite. Leur discussion mêle habitude, moment présent et avenir.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Berlin","participants":[{"nom":"Paul","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Paul","texte":"Wohnst du schon lange in Berlin?"},{"qui":"Mia","texte":"Ja, ich wohne seit drei Jahren hier. Jeden Samstag laufe ich im Park."},{"qui":"Paul","texte":"Cool! Morgen fahre ich auch nach Berlin."},{"qui":"Mia","texte":"Super! Ich zeige dir die Stadt, und du siehst viel."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit que Mia habite à Berlin « depuis » trois ans.","aide":"C’est une préposition suivie du datif.","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces phrases selon la valeur du présent.","aide":"Cherche l’adverbe de temps : jetzt, jeden…, morgen.","type":"categories","categories":[{"id":"c0","texte":"Moment présent"},{"id":"c1","texte":"Habitude"},{"id":"c2","texte":"Avenir proche"}],"items":[{"id":"i0","texte":"Morgen fahre ich nach Berlin."},{"id":"i1","texte":"Jeden Samstag laufe ich im Park."},{"id":"i2","texte":"Nächste Woche kommt Paul."},{"id":"i3","texte":"Ich lese gerade ein Buch."},{"id":"i4","texte":"Er schläft jetzt."},{"id":"i5","texte":"Montags spielt sie Tennis."}]},{"enonce":"Complète : « Tu dors longtemps et il mange beaucoup. »","aide":"Schlafen : a → ä à du. Essen : e → i à er.","type":"trous","segments":["Du ",0," (schlafen) lange, und er ",1," (essen) viel."],"banque":["schläfst","schläft","esst","isst"]},{"enonce":"Comment dit-on « Je travaille ici depuis deux ans » ?","aide":"Avec seit, l’allemand garde le temps du moment présent.","type":"choix","options":[{"id":"a","texte":"Ich arbeitete seit zwei Jahren hier"},{"id":"b","texte":"Ich habe seit zwei Jahren hier gearbeitet"},{"id":"c","texte":"Ich arbeite seit zwei Jahren hier"},{"id":"d","texte":"Ich werde seit zwei Jahren hier arbeiten"}],"multiple":false},{"enonce":"Remets en ordre : « Demain, il va à Berlin (en voiture). » La phrase commence par Morgen.","aide":"Le complément de temps ouvre la phrase : le verbe vient ensuite, puis le sujet.","type":"ordre","items":[{"id":"a","texte":"Morgen"},{"id":"b","texte":"nach Berlin"},{"id":"c","texte":"er"},{"id":"d","texte":"fährt"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**seit** + datif : une action commencée dans le passé et qui continue. Le verbe reste **au présent**."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c2","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Un même présent dit trois choses : **le moment** (*jetzt, gerade*), **l’habitude** (*jeden Samstag, montags*) et **l’avenir proche** (*morgen, nächste Woche*)."},{"cle":{"type":"trous","trous":[["schlafst"],["isst"]]},"affichage":"schläfst · isst","explication":"**Du schläfst lange, und er isst viel.** *schlafen* : a → ä ; *essen* : e → i à la 3e personne."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Ich arbeite seit zwei Jahren hier.** *seit* + présent pour une action commencée dans le passé qui dure encore."},{"cle":{"type":"ordre","ids":["a","d","c","b"]},"explication":"**Morgen fährt er nach Berlin.** Le présent suffit pour dire l’avenir ; *fahren* change de voyelle à *er* (a → ä)."}]$ex$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le petit renard","competence":"comprendre-langue","situation":"Un conte raconte l’histoire d’un renard et d’une pomme. Les contes se racontent au prétérit : repère-le.","documents":[{"id":"conte","type":"texte","genre":"recit","titre":"Der kleine Fuchs","blocs":["Es war einmal ein kleiner Fuchs. Er ging durch den Wald und fand einen Apfel. Er nahm ihn und kam nach Hause. Dort sah er seine Mutter und gab ihr den Apfel."],"source":"Conte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les prétérits de « gehen » et de « finden ».","aide":"Ce sont deux verbes forts : la voyelle a changé.","type":"zone","document":"conte","multiple":true},{"enonce":"Associe chaque infinitif à son prétérit, tel qu’il apparaît dans le conte.","aide":"Dans le conte, retrouve la forme de chaque verbe.","type":"association","gauche":[{"id":"g0","texte":"kommen"},{"id":"g1","texte":"sehen"},{"id":"g2","texte":"geben"},{"id":"g3","texte":"nehmen"}],"droite":[{"id":"d0","texte":"sah"},{"id":"d1","texte":"kam"},{"id":"d2","texte":"nahm"},{"id":"d3","texte":"gab"}]},{"enonce":"Complète : « Il était une fois un renard. »","aide":"C’est le prétérit de sein.","type":"trous","segments":["Es ",0," einmal ein Fuchs."],"banque":["war","hatte","ist","wurde"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12"]},"explication":"**ging** (*gehen*) et **fand** (*finden*) : verbes forts, voyelle modifiée et aucune terminaison à la 3e personne."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**kam**, **sah**, **gab**, **nahm** : des prétérits forts, sans terminaison à la 3e personne du singulier."},{"cle":{"type":"trous","trous":[["war"]]},"affichage":"war","explication":"**Es war einmal ein Fuchs.** *war* est le prétérit de *sein*."}]$ex$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où étais-tu hier ?","competence":"analyser-document","situation":"Eva et Jonas échangent des SMS. Observe quels verbes sont au prétérit et lesquels sont au parfait.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Gestern","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Wo warst du gestern? Ich konnte dich nicht erreichen."},{"qui":"Jonas","texte":"Ich war bei Oma. Ich hatte kein Handy dabei."},{"qui":"Eva","texte":"Und was habt ihr gemacht?"},{"qui":"Jonas","texte":"Wir haben Karten gespielt, und ich musste Kuchen essen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les cinq prétérits : ce sont les seuls que la langue parlée garde.","aide":"Cherche les formes de sein, haben et des modaux.","type":"zone","document":"sms","multiple":true},{"enonce":"Pourquoi Jonas dit-il « Wir haben Karten gespielt » plutôt que « Wir spielten Karten » ?","aide":"Les verbes ordinaires se racontent au parfait dans un message.","type":"choix","options":[{"id":"a","texte":"Parce que spielen est un verbe fort qui n’a pas de prétérit"},{"id":"b","texte":"Parce que Karten est au pluriel et exige le parfait"},{"id":"c","texte":"À l’oral on raconte au parfait, sauf avec sein, haben et les modaux"},{"id":"d","texte":"Parce que le prétérit n’existe pas pour les verbes faibles"}],"multiple":false},{"enonce":"Complète avec « sein » et « haben » : « Où étiez-vous hier, et aviez-vous faim ? »","aide":"Ihr : le prétérit se termine par -t pour ihr.","type":"trous","segments":["Wo ",0," ihr gestern, und ",1," ihr Hunger?"],"banque":["waren","hattet","wart","hatten"]},{"enonce":"Associe chaque modal à son prétérit.","aide":"Pas d’inflexion : on enlève le tréma et on ajoute -te.","type":"association","gauche":[{"id":"g0","texte":"können"},{"id":"g1","texte":"dürfen"},{"id":"g2","texte":"müssen"},{"id":"g3","texte":"wollen"}],"droite":[{"id":"d0","texte":"konnte"},{"id":"d1","texte":"wollte"},{"id":"d2","texte":"durfte"},{"id":"d3","texte":"musste"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m5","m10","m14","m29"]},"explication":"**warst, war, hatte, konnte, musste** : *sein*, *haben* et les modaux gardent le prétérit à l’oral."},{"cle":{"type":"choix","ids":["c"]},"explication":"À l’oral, on raconte au **parfait**. Seuls *sein*, *haben*, *werden* et les modaux gardent le prétérit."},{"cle":{"type":"trous","trous":[["wart"],["hattet"]]},"affichage":"wart · hattet","explication":"**Wo wart ihr gestern, und hattet ihr Hunger?** *ihr wart*, *ihr hattet*."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Prétérit des modaux : **konnte, durfte, musste, wollte** : sans inflexion, avec *-te*."}]$ex$::jsonb),
  ('ef0289ad-13b1-53f9-9766-e3dc59375a88'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Récit écrit, message oral","competence":"raisonner","situation":"Lea raconte sa soirée deux fois : dans un petit récit écrit, puis dans un message à Max. Compare les temps utilisés.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Ein langer Abend","blocs":["Nachdem Lea nach Hause gekommen war, aß sie schnell. Sie hatte lange gearbeitet. Dann nahm sie ihr Buch und las bis elf Uhr. Am nächsten Morgen blieb sie lange im Bett, weil sie spät eingeschlafen war."],"source":"Récit écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Max fragt","participants":[{"nom":"Max","emoji":"👦","cote":"gauche"},{"nom":"Lea","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Max","texte":"Wie war dein Abend?"},{"qui":"Lea","texte":"Ich habe bis elf gelesen. Ich bin spät eingeschlafen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois auxiliaires du plus-que-parfait.","aide":"Ce sont des prétérits de sein ou de haben suivis d’un participe II.","type":"zone","document":"recit","multiple":true},{"enonce":"Remets en ordre : « Après que Tom avait travaillé, il mangea. » La phrase commence par Nachdem.","aide":"Après nachdem, le plus-que-parfait finit la subordonnée ; ensuite, le verbe de la principale ouvre.","type":"ordre","items":[{"id":"a","texte":"Tom"},{"id":"b","texte":"er"},{"id":"c","texte":"hatte"},{"id":"d","texte":"gearbeitet"},{"id":"e","texte":"Nachdem"},{"id":"f","texte":"aß"}]},{"enonce":"Range ces verbes selon la famille de leur prétérit.","aide":"Faible : -te seulement. Fort : voyelle changée. Mixte : les deux.","type":"categories","categories":[{"id":"c0","texte":"Faible"},{"id":"c1","texte":"Fort"},{"id":"c2","texte":"Mixte"}],"items":[{"id":"i0","texte":"denken → dachte"},{"id":"i1","texte":"lernen → lernte"},{"id":"i2","texte":"spielen → spielte"},{"id":"i3","texte":"gehen → ging"},{"id":"i4","texte":"bringen → brachte"},{"id":"i5","texte":"nehmen → nahm"}]},{"enonce":"Les deux documents racontent la même soirée. Pourquoi ne choisissent-ils pas le même temps ?","aide":"Compare un récit écrit à un SMS : le registre change.","type":"choix","options":[{"id":"a","texte":"Après nachdem, le prétérit est toujours remplacé par le parfait"},{"id":"b","texte":"Le récit écrit se raconte au prétérit, le message oral au parfait"},{"id":"c","texte":"Lea est une enfant, Max un adulte : l’âge décide du temps"},{"id":"d","texte":"Le prétérit est réservé aux verbes forts, le parfait aux faibles"}],"multiple":false},{"enonce":"Touche les deux auxiliaires du parfait dans le message de Lea.","aide":"Ils sont devant gelesen et eingeschlafen.","type":"zone","document":"sms","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m10","m35"]},"explication":"**war** (… gekommen), **hatte** (… gearbeitet), **war** (… eingeschlafen) : prétérit de l’auxiliaire + participe II."},{"cle":{"type":"ordre","ids":["e","a","d","c","f","b"]},"explication":"**Nachdem Tom gearbeitet hatte, aß er.** Subordonnée : participe puis auxiliaire à la fin ; principale : verbe avant le sujet."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c1","i4":"c2","i5":"c1"}},"explication":"**Faibles** : *spielte, lernte* ; **forts** : *ging, nahm* ; **mixtes** : *brachte, dachte* (radical modifié et terminaison -te)."},{"cle":{"type":"choix","ids":["b"]},"explication":"En allemand, **prétérit** et **parfait** s’opposent par le registre : écrit narratif pour l’un, oral et messages pour l’autre."},{"cle":{"type":"zone","ids":["m5","m10"]},"explication":"**habe** (… gelesen) et **bin** (… eingeschlafen) : auxiliaires du parfait ; *einschlafen* est un changement d’état, donc *sein*."}]$ex$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Hambourg","competence":"comprendre-langue","situation":"Lukas écrit à sa mère depuis Hambourg. Il raconte sa journée avec le temps des lettres et des messages : le parfait.","documents":[{"id":"postkarte","type":"texte","genre":"lettre","titre":"Liebe Mama","blocs":["Liebe Mama, heute habe ich Hamburg gesehen. Wir sind mit dem Schiff gefahren, und ich habe viele Fotos gemacht. Am Abend sind wir ins Hotel gegangen. Bis bald!"],"source":"Carte postale écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes de verbes de déplacement : ils se conjuguent avec sein.","aide":"Ils sont précédés de « sind » : on va d’un point à un autre.","type":"zone","document":"postkarte","multiple":true},{"enonce":"Touche les deux participes qui se conjuguent avec haben.","aide":"Ils sont précédés de « habe ».","type":"zone","document":"postkarte","multiple":true},{"enonce":"Complète : « J’ai vu un film. »","aide":"Sehen n’exprime pas un déplacement.","type":"trous","segments":["Ich ",0," einen Film gesehen."],"banque":["habe","hat","bin","ist"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m25"]},"explication":"**gefahren** et **gegangen** : verbes de déplacement, donc *sind … gefahren*, *sind … gegangen*."},{"cle":{"type":"zone","ids":["m6","m18"]},"explication":"**gesehen** et **gemacht** : *sehen* et *machen* prennent *haben*."},{"cle":{"type":"trous","trous":[["habe"]]},"affichage":"habe","explication":"**Ich habe einen Film gesehen.** *sehen* prend *haben*."}]$ex$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un jeudi bien rempli","competence":"manier-langue","situation":"Ben raconte sa journée de jeudi dans un courriel. Les participes de son texte se forment de quatre façons différentes.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Mein Donnerstag","blocs":["Gestern habe ich viel erlebt. Ich bin früh aufgestanden und habe mit Oma telefoniert. Sie hat mir eine Geschichte erzählt, und ich habe alles verstanden. Danach habe ich Mathe gelernt und Pizza gegessen."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux participes qui n’ont pas de ge- à cause d’un préverbe inséparable.","aide":"Ils commencent par er- et ver-.","type":"zone","document":"mail","multiple":true},{"enonce":"Touche le participe où ge- s’est glissé entre le préverbe et le radical.","aide":"Il commence par auf-.","type":"zone","document":"mail","multiple":false},{"enonce":"Écris les participes II.","aide":"Séparable : ge- au milieu. En -ieren ou préverbe inséparable : pas de ge-.","type":"trous","segments":["einladen → ",0," · reparieren → ",1," · bezahlen → ",2]},{"enonce":"Pourquoi Ben dit-il « Ich bin früh aufgestanden » avec « bin » ?","aide":"Passer de couché à debout, c’est changer d’état.","type":"choix","options":[{"id":"a","texte":"Ben parle de lui-même"},{"id":"b","texte":"auf- est un préverbe inséparable"},{"id":"c","texte":"Tous les verbes séparables prennent sein"},{"id":"d","texte":"aufstehen exprime un changement d’état"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m24"]},"explication":"**erzählt** et **verstanden** : les préverbes *er-* et *ver-* sont inséparables, donc pas de ge-."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**aufgestanden** : le ge- s’intercale dans un verbe séparable (*auf* + *ge* + *standen*)."},{"cle":{"type":"trous","trous":[["eingeladen"],["repariert"],["bezahlt"]]},"affichage":"eingeladen · repariert · bezahlt","explication":"**eingeladen** (séparable), **repariert** (-ieren) et **bezahlt** (préverbe be- inséparable)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**aufstehen** : changement d’état, donc *sein* au parfait."}]$ex$::jsonb),
  ('7435e27a-38d0-58f2-9f8f-342b80bf673d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La classe 9b à Prague","competence":"raisonner","situation":"Pendant la sortie scolaire, un élève écrit à sa professeure, puis un SMS compare le parfait et le prétérit. Deux documents, une question : quel temps, pourquoi ?","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"An Frau Wolf","blocs":["Liebe Frau Wolf, wir sind gut in Prag gelandet. Am Montag haben wir das Schloss besucht. Ich glaube, dass alle viel gelernt haben. Leider ist Elias im Zug eingeschlafen, weil er schlecht geschlafen hat."],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Der Film","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Gestern habe ich einen Film gesehen."},{"qui":"Ana","texte":"Welchen?"},{"qui":"Tom","texte":"Er war lustig. Ich habe viel gelacht."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux auxiliaires qui ferment une subordonnée, après le participe.","aide":"Ils sont après « gelernt » et « geschlafen ».","type":"zone","document":"mail","multiple":true},{"enonce":"Remets en ordre : « Il dit qu’elle est restée à la maison. » La phrase commence par Er sagt.","aide":"Après dass, tout part à la fin : le participe, puis l’auxiliaire.","type":"ordre","items":[{"id":"a","texte":"sie"},{"id":"b","texte":"dass"},{"id":"c","texte":"geblieben"},{"id":"d","texte":"ist"},{"id":"e","texte":"Er sagt"},{"id":"f","texte":"zu Hause"}]},{"enonce":"Complète avec ist ou sind : « Anna est partie à Cologne et ses parents sont restés à la maison. »","aide":"Reisen et bleiben se conjuguent avec sein ; accorde avec le sujet.","type":"trous","segments":["Anna ",0," nach Köln gereist, und ihre Eltern ",1," zu Hause geblieben."],"banque":["hat","sind","ist","haben"]},{"enonce":"Touche l’unique verbe de ce SMS qui est au prétérit.","aide":"Il décrit le film : il était drôle.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi Tom dit-il « habe gesehen » mais « war » ?","aide":"Pense aux verbes qui gardent le prétérit même à l’oral.","type":"choix","options":[{"id":"a","texte":"Parce que Film est masculin et exige war au lieu de ist"},{"id":"b","texte":"Parce que le parfait ne s’emploie jamais avec lustig"},{"id":"c","texte":"Parce que war est le participe II de sein dans cette phrase"},{"id":"d","texte":"À l’oral, sein garde le prétérit, les autres verbes le parfait"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22","m33"]},"explication":"**haben** et **hat** sont à la toute fin : dans une subordonnée, l’auxiliaire du parfait vient après le participe."},{"cle":{"type":"ordre","ids":["e","b","a","f","c","d"]},"explication":"**Er sagt, dass sie zu Hause geblieben ist.** Subordonnée : participe II puis auxiliaire conjugué, tout à la fin."},{"cle":{"type":"trous","trous":[["ist"],["sind"]]},"affichage":"ist · sind","explication":"**Anna ist nach Köln gereist, und ihre Eltern sind zu Hause geblieben.** *reisen* (déplacement) et *bleiben* prennent *sein*."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**war** : le prétérit de *sein*, même à l’oral. Les autres verbes sont au parfait."},{"cle":{"type":"choix","ids":["d"]},"explication":"À l’oral, on emploie le **parfait** pour presque tous les verbes, mais *sein*, *haben*, *werden* et les modaux restent au **prétérit** : *Er war lustig*."}]$ex$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets de l’été","competence":"comprendre-langue","situation":"Marie demande à Paul ce qu’il fera cet été. Il répond au futur : repère la construction werden + infinitif.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Sommer","participants":[{"nom":"Marie","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marie","texte":"Was wirst du im Sommer machen?"},{"qui":"Paul","texte":"Ich werde nach Italien fahren. Meine Schwester wird auch kommen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois formes conjuguées de « werden ».","aide":"Elles sont en 2e position : wirst, werde, wird.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche les deux infinitifs qui ferment les phrases au futur.","aide":"Ils sont tout à la fin de leur phrase.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète : « Tu travailleras en juillet et nous nous baignerons en août. »","aide":"Du : wirst. Wir : werden.","type":"trous","segments":["Du ",0," im Juli arbeiten, und wir ",1," im August schwimmen."],"banque":["werden","wird","werdet","wirst"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m13"]},"explication":"**wirst, werde, wird** : le présent de *werden* est l’auxiliaire du futur."},{"cle":{"type":"zone","ids":["m10","m15"]},"explication":"**fahren** et **kommen** : au futur, l’infinitif part à la fin et *werden* reste en 2e position."},{"cle":{"type":"trous","trous":[["wirst"],["werden"]]},"affichage":"wirst · werden","explication":"**Du wirst im Juli arbeiten, und wir werden im August schwimmen.** *werden* + infinitif."}]$ex$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bulletin météo","competence":"analyser-texte","situation":"La radio locale annonce le temps des prochains jours. Certaines phrases emploient le futur, d’autres le présent : à toi de comprendre quand le futur est utile.","documents":[{"id":"wetter","type":"texte","genre":"article","titre":"Das Wetter","blocs":["Morgen regnet es im Norden. Im Süden wird es sonnig sein. Am Samstag wird es dann wärmer werden."],"source":"Bulletin écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au présent qui exprime ici l’avenir.","aide":"Un adverbe de temps (morgen) suffit à situer l’action.","type":"zone","document":"wetter","multiple":false},{"enonce":"Touche les deux « wird » qui forment un futur avec un infinitif.","aide":"Ils sont suivis de « sein » et de « werden » à l’infinitif.","type":"zone","document":"wetter","multiple":true},{"enonce":"Range ces phrases : le présent suffit-il, ou le futur est-il utile ?","aide":"Un adverbe de temps rend le futur inutile ; une promesse ou un ordre l’appelle.","type":"categories","categories":[{"id":"c0","texte":"Le présent suffit"},{"id":"c1","texte":"Le futur est utile"}],"items":[{"id":"i0","texte":"Du wirst jetzt aufräumen!"},{"id":"i1","texte":"Am Montag habe ich Training."},{"id":"i2","texte":"Ich werde dir helfen."},{"id":"i3","texte":"Nächste Woche kommt Tom."},{"id":"i4","texte":"Das wird nicht einfach sein."},{"id":"i5","texte":"Morgen fahre ich nach Wien."}]},{"enonce":"Complète : « Ne t’inquiète pas, je ne t’oublierai pas. »","aide":"Ich : la forme de werden est en -e.","type":"trous","segments":["Keine Sorge, ich ",0," dich nicht vergessen."],"banque":["wirst","wird","werde","werden"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**regnet** est au présent : avec *morgen*, le présent suffit pour parler de l’avenir."},{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**wird … sein** et **wird … werden** : *werden* + infinitif à la fin = futur."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Avec un **adverbe de temps**, le présent suffit. Sans repère de temps, pour une **promesse**, une **prédiction** ou une **insistance**, on emploie le futur."},{"cle":{"type":"trous","trous":[["werde"]]},"affichage":"werde","explication":"**Keine Sorge, ich werde dich nicht vergessen.** Une promesse, sans repère de temps : le futur s’impose."}]$ex$::jsonb),
  ('a82490ac-3425-5595-91bb-714161fb7cdf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Où est donc Max ?","competence":"raisonner","situation":"Max ne répond pas au téléphone. Clara et Ben cherchent à comprendre. Attention : un futur allemand ne parle pas toujours de l’avenir.","documents":[{"id":"dial","type":"dialogue","modele":"sms","titre":"Wo ist Max?","participants":[{"nom":"Clara","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Clara","texte":"Wo ist Max? Er antwortet nicht."},{"qui":"Ben","texte":"Er wird wohl schlafen."},{"qui":"Clara","texte":"Dann wird er es vergessen haben!"},{"qui":"Ben","texte":"Er wird bestimmt bald kommen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Associe chaque phrase à sa traduction.","aide":"Tous commencent par werden, mais ce qui suit change le sens.","type":"association","gauche":[{"id":"g0","texte":"Er wird wohl schlafen"},{"id":"g1","texte":"Er wird es vergessen haben"},{"id":"g2","texte":"Er wird bestimmt bald kommen"},{"id":"g3","texte":"Er wird Arzt"}],"droite":[{"id":"d0","texte":"Il doit dormir"},{"id":"d1","texte":"Il viendra sûrement bientôt"},{"id":"d2","texte":"Il a dû l’oublier"},{"id":"d3","texte":"Il devient médecin"}]},{"enonce":"Touche le petit mot qui transforme ce futur en supposition.","aide":"Il se traduit par « sans doute, probablement ».","type":"zone","document":"dial","multiple":false},{"enonce":"Range ces phrases : vrai futur ou supposition sur le présent ?","aide":"Cherche wohl, ou un repère comme morgen ou bald.","type":"categories","categories":[{"id":"c0","texte":"Futur (l’avenir)"},{"id":"c1","texte":"Supposition (le présent)"}],"items":[{"id":"i0","texte":"Wir werden nächste Woche reisen."},{"id":"i1","texte":"Er wird wohl zu Hause sein."},{"id":"i2","texte":"Sie wird wohl noch schlafen."},{"id":"i3","texte":"Ich werde dir morgen helfen."},{"id":"i4","texte":"Das Konzert wird bald beginnen."},{"id":"i5","texte":"Er wird wohl krank sein."}]},{"enonce":"Remets en ordre : « Je crois qu’il viendra. » La phrase commence par Ich glaube.","aide":"En subordonnée, c’est werden qui ferme la phrase, après l’infinitif.","type":"ordre","items":[{"id":"a","texte":"er"},{"id":"b","texte":"wird"},{"id":"c","texte":"Ich glaube"},{"id":"d","texte":"dass"},{"id":"e","texte":"kommen"}]},{"enonce":"Complète : « Elle a dû rater le bus. »","aide":"Le futur II se forme avec werden + participe II + infinitif de l’auxiliaire.","type":"trous","segments":["Sie wird den Bus verpasst ",0,"."],"banque":["worden","sein","hat","haben"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"*wohl* + futur = supposition sur le présent ; futur II = supposition sur le passé ; *bald* = vrai futur ; *werden* + nom = devenir."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**wohl** renforce la supposition : *Er wird wohl schlafen* = « il doit dormir »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Avec **wohl**, le futur dit une hypothèse sur le présent ; avec un repère comme **morgen** ou **bald**, il parle vraiment de l’avenir."},{"cle":{"type":"ordre","ids":["c","d","a","e","b"]},"explication":"**Ich glaube, dass er kommen wird.** Subordonnée : l’infinitif, puis *werden* conjugué en dernier."},{"cle":{"type":"trous","trous":[["haben"]]},"affichage":"haben","explication":"**Sie wird den Bus verpasst haben.** Futur II : *werden* + participe + *haben*, une supposition sur le passé."}]$ex$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une recette de crêpes","competence":"comprendre-langue","situation":"Une recette de Pfannkuchen donne ses consignes à l’impératif. Observe comment l’ordre est formé quand on dit « tu ».","documents":[{"id":"rezept","type":"fiche","modele":"recette","entete":"Pfannkuchen","sousTitre":"Für zwei Personen","emoji":"🥞","lignes":[{"texte":"Nimm eine große Schüssel.","id":"z1"},{"texte":"Gib Mehl, Eier und Milch dazu.","id":"z2"},{"texte":"Rühre alles gut.","id":"z3"},{"texte":"Mach die Pfanne heiß.","id":"z4"}],"pied":"Guten Appetit!","source":"Recette écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux consignes dont l’impératif a gardé le changement de voyelle e → i.","aide":"Cherche nehmen et geben.","type":"zone","document":"rezept","multiple":true},{"enonce":"Associe chaque personne à l’impératif de « kommen ».","aide":"Seuls Sie et wir gardent le pronom.","type":"association","gauche":[{"id":"g0","texte":"du"},{"id":"g1","texte":"ihr"},{"id":"g2","texte":"Sie"},{"id":"g3","texte":"wir"}],"droite":[{"id":"d0","texte":"Kommt!"},{"id":"d1","texte":"Kommen wir!"},{"id":"d2","texte":"Komm!"},{"id":"d3","texte":"Kommen Sie!"}]},{"enonce":"Remets en ordre : « Donne-moi le sel ! »","aide":"Le verbe ouvre la phrase, sans pronom : le datif vient avant l’accusatif.","type":"ordre","items":[{"id":"a","texte":"mir"},{"id":"b","texte":"Gib"},{"id":"c","texte":"das Salz"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Nimm** (*nehmen*) et **Gib** (*geben*) gardent la voyelle des 2e et 3e personnes : *du nimmst*, *du gibst*."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**Komm!** (du), **Kommt!** (ihr), **Kommen Sie!** (politesse), **Kommen wir!** (allons-y)."},{"cle":{"type":"ordre","ids":["b","a","c"]},"explication":"**Gib mir das Salz!** Le verbe ouvre la phrase, sans *du*."}]$ex$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les consignes de Frau Weiß","competence":"manier-langue","situation":"Dans la classe, Frau Weiß donne des consignes à tous les élèves, puis à Jonas seul. Écoute bien à qui elle parle.","documents":[{"id":"klasse","type":"dialogue","modele":"sms","titre":"Im Klassenzimmer","participants":[{"nom":"Frau Weiß","emoji":"👩","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Frau Weiß","texte":"Seid bitte ruhig und öffnet eure Hefte. Jonas, lies den Text. Sprich laut und langsam!"},{"qui":"Jonas","texte":"Soll ich auch die Fragen lesen?"},{"qui":"Frau Weiß","texte":"Ja, aber nicht so schnell."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux impératifs adressés à toute la classe (ihr).","aide":"Ils se terminent par -t ou -d et n’ont pas de pronom.","type":"zone","document":"klasse","multiple":true},{"enonce":"Touche les deux impératifs adressés à Jonas seul (du).","aide":"Ils n’ont pas de terminaison et gardent e → ie et e → i.","type":"zone","document":"klasse","multiple":true},{"enonce":"Écris l’impératif à « du ».","aide":"Avec a → ä, l’inflexion se perd à l’impératif.","type":"trous","segments":["fahren : ",0," bitte langsam! · schlafen : ",1," jetzt!"]},{"enonce":"Pourquoi dit-on « Arbeite! » avec un -e final ?","aide":"Regarde la dernière lettre du radical : arbeit-.","type":"choix","options":[{"id":"a","texte":"Parce que tous les impératifs prennent un -e final"},{"id":"b","texte":"Parce que le radical finit par -t : le e est obligatoire"},{"id":"c","texte":"Parce que arbeiten est un verbe fort qui change de voyelle"},{"id":"d","texte":"Parce que arbeiten possède un préverbe séparable"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m4"]},"explication":"**Seid** (*sein*) et **öffnet** (*öffnen*) sont des impératifs à *ihr* : la forme du présent, sans pronom."},{"cle":{"type":"zone","ids":["m8","m11"]},"explication":"**Lies** (*lesen*) et **Sprich** (*sprechen*) : le radical sans terminaison, avec la voyelle des 2e et 3e personnes."},{"cle":{"type":"trous","trous":[["fahr","fahre"],["schlaf","schlafe"]]},"affichage":"Fahr · Schlaf","explication":"**Fahr!** et **Schlaf!** : l’inflexion *a → ä* disparaît à l’impératif (alors que *du fährst*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Arbeite!** : après -d, -t, -ig, le *-e* est obligatoire. Ailleurs, il est facultatif et soutenu (*Gehe!*)."}]$ex$::jsonb),
  ('8ddb8658-38c9-5fad-bcfd-9f0a258ecbec'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ordres, consignes et services","competence":"raisonner","situation":"Dans un immeuble, l’affiche du règlement mêle plusieurs façons d’ordonner. Plus loin, deux amis se demandent un service : on adoucit l’ordre autrement.","documents":[{"id":"haus","type":"fiche","modele":"affiche","entete":"Hausordnung","sousTitre":"Bitte lesen","emoji":"🏢","lignes":[{"texte":"Nicht rauchen!","id":"z1"},{"texte":"Bitte Schuhe ausziehen!","id":"z2"},{"texte":"Seien Sie bitte leise.","id":"z3"},{"texte":"Schließen Sie die Tür.","id":"z4"}],"pied":"Danke!","source":"Affiche écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Ein Gefallen","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hilf mir mal, Tom! Ich finde meinen Schlüssel nicht."},{"qui":"Tom","texte":"Such doch im Auto. Gib mir bitte deine Tasche."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux consignes données à l’infinitif, sans verbe conjugué.","aide":"Elles ne contiennent ni Sie ni forme conjuguée.","type":"zone","document":"haus","multiple":true},{"enonce":"Touche la ligne qui emploie l’impératif de politesse du verbe « sein ».","aide":"Cherche une forme de sein suivie de Sie.","type":"zone","document":"haus","multiple":false},{"enonce":"Touche les trois petits mots qui adoucissent l’ordre.","aide":"Ils se traduisent par un peu, donc, s’il te plaît.","type":"zone","document":"sms","multiple":true},{"enonce":"Remets en ordre : « Appelle-moi demain ! »","aide":"Le verbe ouvre la phrase ; le préverbe séparable part à la fin.","type":"ordre","items":[{"id":"a","texte":"morgen"},{"id":"b","texte":"an"},{"id":"c","texte":"Ruf"},{"id":"d","texte":"mich"}]},{"enonce":"Associe chaque pronom à l’impératif de « gehen ».","aide":"Seuls Sie et wir gardent le pronom.","type":"association","gauche":[{"id":"g0","texte":"du"},{"id":"g1","texte":"ihr"},{"id":"g2","texte":"Sie"},{"id":"g3","texte":"wir"}],"droite":[{"id":"d0","texte":"Gehen Sie!"},{"id":"d1","texte":"Geh!"},{"id":"d2","texte":"Gehen wir!"},{"id":"d3","texte":"Geht!"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**Nicht rauchen!** et **Bitte Schuhe ausziehen!** : l’infinitif seul sert aux panneaux et aux consignes."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Seien Sie bitte leise** : impératif de politesse de *sein* ; le pronom *Sie* se maintient."},{"cle":{"type":"zone","ids":["m2","m10","m15"]},"explication":"**mal**, **doch**, **bitte** : sans eux, l’impératif paraîtrait sec."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"**Ruf mich morgen an!** *anrufen* : le préverbe *an* passe à la fin."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**Geh!** (du), **Geht!** (ihr), **Gehen Sie!** (politesse), **Gehen wir!** (allons-y)."}]$ex$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Au café","competence":"comprendre-langue","situation":"Dans un café de Vienne, un client commande avec politesse. Observe les formes qui adoucissent la demande.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Im Café","participants":[{"nom":"Kellnerin","emoji":"👩","cote":"gauche"},{"nom":"Gast","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Kellnerin","texte":"Guten Tag! Was möchten Sie?"},{"qui":"Gast","texte":"Ich hätte gern einen Tee. Könnten Sie mir auch ein Wasser bringen?"},{"qui":"Kellnerin","texte":"Natürlich. Würden Sie lieber drinnen sitzen?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre formes de politesse (subjonctif II).","aide":"Ce sont möchten, hätte, Könnten et Würden.","type":"zone","document":"cafe","multiple":true},{"enonce":"Pourquoi dit-on « Ich hätte gern einen Tee » plutôt que « Ich will einen Tee » ?","aide":"Pense à l’effet produit sur le serveur.","type":"choix","options":[{"id":"a","texte":"Parce que gern est obligatoire avec le verbe haben"},{"id":"b","texte":"Parce que l’infinitif doit venir en première position"},{"id":"c","texte":"Parce que hätte est le prétérit de haben et parle du passé"},{"id":"d","texte":"Il rend la demande polie : le présent ferait un ordre brusque"}],"multiple":false},{"enonce":"Associe chaque verbe à son subjonctif II simple.","aide":"On part du prétérit et on ajoute une inflexion.","type":"association","gauche":[{"id":"g0","texte":"sein"},{"id":"g1","texte":"haben"},{"id":"g2","texte":"können"},{"id":"g3","texte":"werden"}],"droite":[{"id":"d0","texte":"wäre"},{"id":"d1","texte":"würde"},{"id":"d2","texte":"könnte"},{"id":"d3","texte":"hätte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m6","m10","m18"]},"explication":"**möchten, hätte, Könnten, Würden** : le subjonctif II adoucit la phrase et la rend polie."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **subjonctif II** est l’outil de la politesse : *Ich hätte gern…* sonne comme une demande, *Ich will…* comme un ordre."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**wäre, hätte, könnte, würde** : formes simples fréquentes, construites sur le prétérit avec inflexion."}]$ex$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Si j’étais riche","competence":"manier-langue","situation":"Dans sa lettre, Jonas rêve d’une vie au bord de la mer. Pour rêver, l’allemand utilise le subjonctif II.","documents":[{"id":"traum","type":"texte","genre":"lettre","titre":"Mein Traum","blocs":["Wenn ich reich wäre, würde ich ein Haus am Meer kaufen. Hätte ich dort ein Boot, würde ich jeden Tag segeln. Aber ich habe nur wenig Geld, deshalb arbeite ich im Sommer."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux formes simples du subjonctif II.","aide":"Ce sont des formes de sein et de haben.","type":"zone","document":"traum","multiple":true},{"enonce":"Complète : « Si nous avions plus de temps, nous resterions plus longtemps. »","aide":"Hypothèse : subjonctif II de haben, puis würde + infinitif.","type":"trous","segments":["Wenn wir mehr Zeit ",0,", ",1," wir länger bleiben."],"banque":["hätten","würden","hatten","wären"]},{"enonce":"Remets en ordre, sans « wenn » : « S’il était ici, il aiderait. » La phrase commence par Wäre.","aide":"Sans wenn, le verbe prend la première place ; l’infinitif de la principale est à la fin.","type":"ordre","items":[{"id":"a","texte":"er"},{"id":"b","texte":"Wäre"},{"id":"c","texte":"würde"},{"id":"d","texte":"er hier"},{"id":"e","texte":"helfen"}]},{"enonce":"Associe chaque phrase à son emploi.","aide":"Souhait, conseil, politesse, irréel : les trois emplois et un tour sans wenn.","type":"association","gauche":[{"id":"g0","texte":"Wenn er nur hier wäre!"},{"id":"g1","texte":"Du solltest mehr schlafen"},{"id":"g2","texte":"Könnten Sie mir helfen?"},{"id":"g3","texte":"Hätte ich Zeit, würde ich kommen"}],"droite":[{"id":"d0","texte":"une demande polie"},{"id":"d1","texte":"un conseil"},{"id":"d2","texte":"une hypothèse irréelle"},{"id":"d3","texte":"un souhait"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m11"]},"explication":"**wäre** (*sein*) et **Hätte** (*haben*) sont les formes simples. Dans « Hätte ich… », *wenn* a disparu."},{"cle":{"type":"trous","trous":[["hatten"],["wurden"]]},"affichage":"hätten · würden","explication":"**Wenn wir mehr Zeit hätten, würden wir länger bleiben.** *hätten* (forme simple) + *würden* + infinitif."},{"cle":{"type":"ordre","ids":["b","d","c","a","e"]},"explication":"**Wäre er hier, würde er helfen.** Sans *wenn*, le verbe est en première position."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"*wenn nur…* = souhait ; *solltest* = conseil ; *Könnten Sie…* = politesse ; *Hätte ich…, würde ich…* = hypothèse irréelle."}]$ex$::jsonb),
  ('acebc17f-d953-5af6-8129-008553b71d05'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un entraîneur et un caprice de glace","competence":"raisonner","situation":"Dans la presse locale, un entraîneur parle de son équipe. Plus loin, un enfant apprend à demander poliment. Deux documents, plusieurs subjonctifs.","documents":[{"id":"presse","type":"texte","genre":"article","titre":"Der Trainer spricht","blocs":["Der Trainer sagte, er sei zufrieden. Er tut aber so, als ob er alles wüsste. Die Spieler wären lieber im Urlaub."],"source":"Article écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Ein Eis","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Mama","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Ich will ein Eis."},{"qui":"Mama","texte":"Wie bitte? Sag das noch einmal höflich."},{"qui":"Ben","texte":"Ich möchte bitte ein Eis. Könntest du mir Geld geben?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le subjonctif I qui rapporte les paroles de l’entraîneur.","aide":"Il apparaît après « sagte » et se traduit par « il est ».","type":"zone","document":"presse","multiple":false},{"enonce":"Touche le verbe au subjonctif II après « als ob ».","aide":"C’est le verbe qui suit « alles ».","type":"zone","document":"presse","multiple":false},{"enonce":"Touche la forme de « sein » qui dit ce que les joueurs préféreraient.","aide":"Elle s’écrit avec ä.","type":"zone","document":"presse","multiple":false},{"enonce":"Pourquoi la mère de Ben réagit-elle à « Ich will ein Eis » ?","aide":"Compare avec la phrase polie de Ben, plus bas.","type":"choix","options":[{"id":"a","texte":"Le présent sonne comme un ordre brusque"},{"id":"b","texte":"Parce que Ben aurait dû employer l’impératif"},{"id":"c","texte":"Parce que will est un verbe faible mal conjugué"},{"id":"d","texte":"Parce que ein Eis exige un verbe au prétérit"}],"multiple":false},{"enonce":"Remets en ordre : « Pourriez-vous m’aider ? »","aide":"Question : le verbe conjugué ouvre la phrase ; l’infinitif part à la fin.","type":"ordre","items":[{"id":"a","texte":"Sie"},{"id":"b","texte":"mir"},{"id":"c","texte":"helfen"},{"id":"d","texte":"Könnten"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**sei** : subjonctif I de *sein*, typique du discours indirect de la presse. Il suffit de le reconnaître."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**wüsste** : après *als ob*, le subjonctif II est de règle (*wissen* → *wüsste*)."},{"cle":{"type":"zone","ids":["m17"]},"explication":"**wären** : subjonctif II de *sein* ; il exprime ce qui n’est pas réel (« seraient plutôt en vacances »)."},{"cle":{"type":"choix","ids":["a"]},"explication":"*Ich will…* sonne comme un ordre ; **Ich möchte bitte…** et **Könntest du…?** (subjonctif II) rendent la demande acceptable."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Könnten Sie mir helfen?** Subjonctif II de *können*, très poli, en première place pour une question."}]$ex$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois pays, trois façons de dire bonjour","competence":"lire-tableau","situation":"Pour son voyage de classe, Léa prépare une fiche : l’allemand ne se dit pas partout de la même façon. Lis son tableau.","documents":[{"id":"gruss","type":"tableau","titre":"Gleich und doch anders","colonnes":["Sens","Deutschland","Österreich","Schweiz"],"lignes":[["Bonjour","Guten Tag","Grüß Gott","Grüezi"],["Le petit pain","das Brötchen","die Semmel","das Brötli"],["La tomate","die Tomate","der Paradeiser","die Tomate"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche la case qui donne la façon de dire bonjour en Suisse.","aide":"Cherche la colonne « Schweiz », sur la ligne « Bonjour ».","type":"zone","document":"gruss","multiple":false},{"enonce":"Touche le mot que seul un Autrichien emploie pour dire « la tomate ».","aide":"Dans deux colonnes sur trois, le mot est le même. Cherche celui qui change.","type":"zone","document":"gruss","multiple":false},{"enonce":"Dans une boulangerie suisse, tu lis « Brötli » sur une étiquette. Que peux-tu acheter ?","aide":"Regarde la ligne du tableau où les trois mots se ressemblent.","type":"choix","options":[{"id":"a","texte":"Des fromages"},{"id":"b","texte":"Des gâteaux au chocolat"},{"id":"c","texte":"Des tomates"},{"id":"d","texte":"Des petits pains"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"**Grüezi** est la salutation de la Suisse alémanique : on le lit dans la colonne *Schweiz*, ligne « Bonjour »."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"**der Paradeiser** : en Autriche, on ne dit pas *die Tomate*. Les deux autres colonnes ont le même mot."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **Brötli** est le petit pain suisse : *das Brötchen* en Allemagne, *die Semmel* en Autriche."}]$ex$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lukas et Emma : Hochdeutsch ou dialecte ?","competence":"comprendre-langue","situation":"Emma, de Lyon, va passer une semaine chez Lukas, à Zurich. Avant le départ, ils s’écrivent des messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Nachrichten","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Lukas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Hallo Lukas! Ich komme am Samstag. Wie sagt man „Bonjour“ bei euch?"},{"qui":"Lukas","texte":"Bei uns sagt man Grüezi. Zu Hause sprechen wir Schwiizerdütsch, aber in der Schule schreiben wir Hochdeutsch."},{"qui":"Emma","texte":"Ich verstehe nicht alles. Kannst du das bitte wiederholen?"},{"qui":"Lukas","texte":"Kein Problem! Wir sprechen langsam."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui désigne la langue que Lukas parle à la maison.","aide":"C’est le dialecte de la Suisse alémanique.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le mot qui désigne l’allemand « standard » écrit à l’école.","aide":"Ce mot commence par « Hoch ».","type":"zone","document":"sms","multiple":false},{"enonce":"Range chaque situation selon la langue qu’on utilise le plus souvent en Suisse alémanique.","aide":"Le dialecte est la langue de l’oral quotidien ; le Hochdeutsch, celle de l’écrit.","type":"categories","categories":[{"id":"c0","texte":"Dialecte (Schwiizerdütsch)"},{"id":"c1","texte":"Hochdeutsch"}],"items":[{"id":"i0","texte":"Bavarder en famille à table"},{"id":"i1","texte":"Écrire une rédaction pour l’école"},{"id":"i2","texte":"Parler avec sa famille à la maison, tous les jours"},{"id":"i3","texte":"Lire un article de journal"}]},{"enonce":"Complète la phrase qu’Emma écrit pour demander de répéter.","aide":"Le verbe signifie « répéter ».","type":"trous","segments":["Kannst du das bitte ",0,"?"],"banque":["sprechen","wiederholen","sagen","verstehen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"**Schwiizerdütsch** : c’est le dialecte suisse, la langue de tous les jours."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**Hochdeutsch** est l’allemand standard : celui de l’école, des journaux et de l’écrit."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"En Suisse alémanique, le **dialecte** sert à l’oral de tous les jours, le **Hochdeutsch** à l’écrit : journaux, rédactions, textes officiels."},{"cle":{"type":"trous","trous":[["wiederholen"]]},"affichage":"wiederholen","explication":"**Kannst du das bitte wiederholen?** *wiederholen* veut dire « répéter » ; après le modal *kannst*, il reste à l’infinitif, en fin de phrase."}]$ex$::jsonb),
  ('b531b475-2e30-50e9-8969-740d7561a192'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Où a-t-on écrit ces messages ?","competence":"analyser-document","situation":"Trois élèves publient des messages sur un forum d’échange scolaire. À toi de deviner, grâce à leurs mots, de quel pays ils écrivent.","documents":[{"id":"karte","type":"carte","titre":"Deutschsprachige Länder","fond":"europe","cadrage":[4,44,19,55],"regionsCliquables":true,"regions":[{"code":"DEU","teinte":"sable","etiquette":"Deutschland"},{"code":"AUT","teinte":"rose","etiquette":"Österreich"},{"code":"CHE","teinte":"ciel","etiquette":"Schweiz"}],"source":"Fond de carte simplifié"},{"id":"posts","type":"texte","genre":"article","titre":"Drei Nachrichten","blocs":["Mara : Im Supermarkt kaufe ich ein Kilo Paradeiser für die Pizza.","Noah : Jeden Morgen hole ich zwei Brötli beim Bäcker. Dann sage ich „Grüezi“.","Hannah : Ich bin in Köln. Zum Frühstück esse ich ein Brötchen."],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Mara achète des « Paradeiser ». Touche sur la carte le pays d’où elle écrit.","aide":"Quel pays dit « Paradeiser » pour la tomate ?","type":"zone","document":"karte","multiple":false},{"enonce":"Noah achète des « Brötli » et dit « Grüezi ». Touche sur la carte le pays d’où il écrit.","aide":"Deux indices dans son message : le petit pain et la salutation.","type":"zone","document":"karte","multiple":false},{"enonce":"Selon le tableau du cours, range ces mots dans le pays où ils sont typiques, entre la Suisse et l’Autriche.","aide":"Souviens-toi : « Grüezi » est suisse, « Semmel » est autrichien.","type":"categories","categories":[{"id":"c0","texte":"Suisse"},{"id":"c1","texte":"Autriche"}],"items":[{"id":"i0","texte":"die Semmel"},{"id":"i1","texte":"der Paradeiser"},{"id":"i2","texte":"Grüezi"},{"id":"i3","texte":"Uf Widerluege"},{"id":"i4","texte":"Baba"},{"id":"i5","texte":"das Brötli"}]},{"enonce":"Hannah écrit de Köln : « Ich esse ein Brötchen. » Léo en conclut que Hannah « parle mal allemand ». Que lui réponds-tu ?","aide":"Pense à ce que dit le cours sur les variantes et les dialectes.","type":"choix","options":[{"id":"a","texte":"Non : Brötchen est l’allemand standard, sans faute"},{"id":"b","texte":"Non : Hannah parle suisse, et pas allemand du tout"},{"id":"c","texte":"Oui : seul l’allemand d’Autriche est du vrai allemand"},{"id":"d","texte":"Oui : tous les Allemands parlent seulement un dialecte"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["AUT"]},"explication":"Mara écrit d’**Autriche** (*Österreich*) : seul ce pays emploie *der Paradeiser* pour la tomate."},{"cle":{"type":"zone","ids":["CHE"]},"explication":"Noah écrit de **Suisse** (*die Schweiz*) : *das Brötli* et *Grüezi* sont deux mots suisses."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"En **Suisse** : *Grüezi*, *Uf Widerluege*, *das Brötli*. En **Autriche** : *der Paradeiser*, *die Semmel*, *Baba* (au revoir)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Aucune variante n’est « du mauvais allemand » : *Brötchen* est le mot du Hochdeutsch en Allemagne, *Brötli* et *Semmel* sont d’autres façons, tout aussi justes."}]$ex$::jsonb),
  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 1, 1, 5, 20, 3,
