  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bulletin de Mia","competence":"lire-tableau","situation":"Mia reçoit son Zeugnis. En Allemagne, la note 1 est la meilleure et la 6 la pire : il faut bien lire pour comprendre ce que Mia a réussi.","documents":[{"id":"zeugnis","type":"tableau","titre":"Mias Zeugnis","colonnes":["Fach","Note"],"lignes":[["Deutsch",2],["Mathe",3],["Englisch",1],["Sport",2],["Kunst",4]],"enteteLignes":true,"source":"Bulletin écrit pour l’exercice"}],"questions":[{"enonce":"Touche la note dont Mia peut être le plus fière.","aide":"En Allemagne, la meilleure note est la plus petite.","type":"zone","document":"zeugnis","multiple":false},{"enonce":"Calcule la moyenne des cinq notes de Mia.","aide":"Additionne les cinq notes puis divise par 5.","type":"nombre"},{"enonce":"Associe chaque note au mot allemand qui la décrit.","aide":"1 est la meilleure note, 6 la pire.","type":"association","gauche":[{"id":"g0","texte":"1"},{"id":"g1","texte":"2"},{"id":"g2","texte":"4"},{"id":"g3","texte":"6"}],"droite":[{"id":"d0","texte":"sehr gut"},{"id":"d1","texte":"ungenügend"},{"id":"d2","texte":"gut"},{"id":"d3","texte":"ausreichend"}]},{"enonce":"Mia raconte sa meilleure note. Complète sa phrase d’après le bulletin.","aide":"Cherche la matière où la note est 1.","type":"trous","segments":["Ich habe eine Eins in ",0,"!"],"banque":["Englisch","Deutsch","Mathe","Sport"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La meilleure note est **1** (*sehr gut*) : c’est celle de *Englisch*."},{"cle":{"type":"nombre","valeur":2.4,"tolerance":0},"affichage":"2,4","explication":"2 + 3 + 1 + 2 + 4 = 12, et 12 ÷ 5 = **2,4**. Une moyenne proche de 2 (*gut*) est une bonne moyenne."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"1 = *sehr gut* (très bien), 2 = *gut* (bien), 4 = *ausreichend* (passable), 6 = *ungenügend* (très insuffisant)."},{"cle":{"type":"trous","trous":[["englisch"]]},"affichage":"Englisch","explication":"**Ich habe eine Eins in Englisch!** Le bulletin donne 1 en *Englisch* ; *in* + matière introduit la matière notée."}]$ex$::jsonb),
  ('0f6859ec-d31c-51bc-98f7-3666e6a6c7c6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une école, deux emplois du temps","competence":"analyser-document","situation":"Jonas écrit à Camille, sa correspondante française. L’école de Jonas ne ressemble pas tout à fait à la sienne. Une affiche du collège voisin le montre aussi.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Eine E-Mail an Camille","blocs":["Liebe Camille,","bei uns beginnt die Schule um 7:45 Uhr und endet um 13:00 Uhr. Eine Stunde dauert 45 Minuten. Oft haben wir zwei Stunden zusammen, eine Doppelstunde.","Meine Schule ist keine Ganztagsschule. Am Nachmittag spiele ich Handball in einem Verein. Nach der Grundschule geht man mit zehn Jahren auf das Gymnasium oder auf die Realschule.","Viele Grüße","Jonas"],"source":"Courriel écrit pour l’exercice"},{"id":"plakat","type":"fiche","modele":"affiche","entete":"Ganztagsschule","sousTitre":"Unsere Schule bleibt bis 16 Uhr offen","emoji":"🏫","lignes":[{"texte":"Montag bis Donnerstag: Unterricht bis 16:00 Uhr","id":"z1"},{"texte":"Mittagessen in der Mensa","id":"z2"},{"texte":"AGs : Fußball, Theater, Chor","id":"z3"}],"pied":"Herzlich willkommen!","teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Combien de minutes dure une Doppelstunde dans l’école de Jonas ?","aide":"Une Stunde dure 45 minutes ; une Doppelstunde, c’est deux Stunden.","type":"nombre","unite":"minutes"},{"enonce":"Touche le mot qui désigne le club où Jonas joue au handball.","aide":"C’est une association, pour le sport, la musique ou les pompiers volontaires.","type":"zone","document":"brief","multiple":false},{"enonce":"Jonas finit à 13 h. Au collège de l’affiche, les cours durent jusqu’à 16 h. Combien d’heures de plus passe-t-on à l’école là-bas ?","aide":"Compare l’heure de fin des deux écoles.","type":"nombre","unite":"heures"},{"enonce":"Une Ganztagsschule garde les élèves l’après-midi. Touche la ligne qui dit où ils déjeunent.","aide":"« Mittagessen » veut dire « repas de midi ».","type":"zone","document":"plakat","multiple":false},{"enonce":"Remets dans l’ordre le parcours d’un élève allemand. Le premier est Kindergarten.","aide":"Pense à l’âge : 3 ans, 6 ans, 10 ans, puis le bac.","type":"ordre","items":[{"id":"a","texte":"Gymnasium"},{"id":"b","texte":"Abitur"},{"id":"c","texte":"Kindergarten"},{"id":"d","texte":"Grundschule"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":90,"tolerance":0},"affichage":"90 minutes","explication":"2 × 45 = **90** minutes : une *Doppelstunde* est faite de deux heures de 45 minutes."},{"cle":{"type":"zone","ids":["m42"]},"explication":"**der Verein** : un club ou une association, très présent dans la vie des Allemands."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 heures","explication":"De 13 h à 16 h, il y a **3** heures de plus. C’est la différence entre une école « du matin » et une *Ganztagsschule*."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Mittagessen in der Mensa** : la cantine (*die Mensa*) fait partie de la journée complète."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"**Kindergarten** (3–6 ans), **Grundschule** (6–10 ans), **Gymnasium** (dès 10 ans), puis l’**Abitur**, le bac allemand."}]$ex$::jsonb),
