   $ex${"titre":"Au menu de la cantine","competence":"analyser-document","situation":"Dans la Mensa de Munich, tous les plats portent des noms composés. Avec le petit lexique, tu peux comprendre ce que tu manges.","documents":[{"id":"menu","type":"fiche","modele":"menu","entete":"Mensa – Speiseplan","sousTitre":"Montag","emoji":"🍽️","lignes":[{"texte":"Kartoffelsuppe","valeur":"1,50 €","id":"z1"},{"texte":"Gemüsepfanne","valeur":"3,20 €","id":"z2"},{"texte":"Apfelkuchen","valeur":"1,80 €","id":"z3"},{"texte":"Schokoladeneis","valeur":"1,20 €","id":"z4"},{"texte":"Orangensaft","valeur":"1,00 €","id":"z5"}],"teinte":"ambre","source":"Menu écrit pour l’exercice"},{"id":"lexikon","type":"tableau","titre":"Lexikon","colonnes":["Wort","Sens"],"lignes":[["die Kartoffel","la pomme de terre"],["das Gemüse","les légumes"],["die Pfanne","la poêle"],["der Apfel","la pomme"],["der Kuchen","le gâteau"],["die Schokolade","le chocolat"],["das Eis","la glace"],["der Saft","le jus"],["die Suppe","la soupe"]],"enteteLignes":true,"source":"Lexique écrit pour l’exercice"}],"questions":[{"enonce":"Touche le plat dont le mot de base est « Pfanne ».","aide":"Le mot de base est le dernier élément du mot.","type":"zone","document":"menu","multiple":false},{"enonce":"Associe chaque plat du menu à son sens, grâce au lexique.","aide":"Lis le mot de droite à gauche : le dernier mot est le mot de base.","type":"association","gauche":[{"id":"g0","texte":"Kartoffelsuppe"},{"id":"g1","texte":"Gemüsepfanne"},{"id":"g2","texte":"Orangensaft"},{"id":"g3","texte":"Schokoladeneis"}],"droite":[{"id":"d0","texte":"glace au chocolat"},{"id":"d1","texte":"soupe de pommes de terre"},{"id":"d2","texte":"jus d’orange"},{"id":"d3","texte":"poêlée de légumes"}]},{"enonce":"Range chaque plat selon son article, qui vient du dernier mot (regarde le lexique).","aide":"Cherche l’article de Saft, Kuchen, Suppe, Pfanne et Eis dans le lexique.","type":"categories","categories":[{"id":"c0","texte":"der"},{"id":"c1","texte":"die"},{"id":"c2","texte":"das"}],"items":[{"id":"i0","texte":"Kartoffelsuppe"},{"id":"i1","texte":"Schokoladeneis"},{"id":"i2","texte":"Orangensaft"},{"id":"i3","texte":"Apfelkuchen"},{"id":"i4","texte":"Gemüsepfanne"}]},{"enonce":"Au dessert, tu veux un jus de pomme. Écris le mot composé allemand, en un seul mot.","aide":"Pomme d’abord, jus ensuite : Apfel + Saft.","type":"texte"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Gemüsepfanne** se termine par *Pfanne* : c’est une « poêlée de légumes » (*Gemüse* + *Pfanne*)."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"On lit à l’envers : *Suppe* (soupe) précisée par *Kartoffel* ; *Pfanne* par *Gemüse* ; *Saft* par *Orange* ; *Eis* par *Schokolade*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0","i3":"c0","i4":"c1"}},"explication":"**der** Orangensaft (*der Saft*), **der** Apfelkuchen (*der Kuchen*) ; **die** Kartoffelsuppe (*die Suppe*), **die** Gemüsepfanne (*die Pfanne*) ; **das** Schokoladeneis (*das Eis*)."},{"cle":{"type":"texte","acceptes":["apfelsaft"]},"affichage":"Apfelsaft","explication":"**Apfelsaft** : *der Apfel* (la pomme) + *der Saft* (le jus). Le mot de base est *Saft*, donc *der Apfelsaft*."}]$ex$::jsonb),
