   $ex$[{"cle":{"type":"zone","ids":["m12","m23","m43"]},"explication":"**clothes, scissors, glasses** n’existent qu’au pluriel. On les compte avec *a pair of* (sauf *clothes*)."},{"cle":{"type":"zone","ids":["m30"]},"explication":"**students’** : pour un pluriel en -s, on ajoute l’apostrophe seule (*the students’ lockers*)."},{"cle":{"type":"trous","trous":[["pairs"]]},"affichage":"pairs","explication":"**pairs** : *scissors* n’existent qu’au pluriel, on les compte avec *a pair of* : *six pairs of scissors*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**My new trousers are too long.** Le nom reste au pluriel, le verbe aussi, et l’adjectif ne prend jamais de -s."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"On dit *a piece of advice*, *a pair of jeans*, *a glass of water*, *a slice of bread*."}]$ex$::jsonb),
