   $ex${"titre":"Une lettre sur un nouvel ami","competence":"comprendre-langue","situation":"Sam écrit à son correspondant pour lui parler de Ben, un nouvel ami. Lis la lettre pour observer les articles.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Letter from Sam","blocs":["Dear Jack,","I have a new friend. His name is Ben. He lives in an old house near the river. Ben has a guitar. The guitar is red. He plays the guitar and football every day.","Write soon!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’article indéfini placé devant un **son de voyelle**.","aide":"Cherche un mot qui commence par une voyelle prononcée.","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi lit-on « **The** guitar is red » ?","aide":"Regarde la phrase juste avant : Ben a déjà « a guitar ».","type":"choix","options":[{"id":"a","texte":"Parce que la phrase est négative"},{"id":"b","texte":"Parce que guitar est un nom indénombrable"},{"id":"c","texte":"Parce que la guitare a déjà été mentionnée"},{"id":"d","texte":"Parce que c’est un instrument inconnu"}],"multiple":false},{"enonce":"Complète avec l’article qui convient.","aide":"C’est le **son** qui compte : *university* commence par [juː].","type":"trous","segments":["I have ",0," umbrella and ",1," university card."],"banque":["an","the","a"]}]}$ex$::jsonb,
