   $ex${"titre":"Le carnet de voyage de Léa","competence":"analyser-texte","situation":"Léa visite Paris avec son frère. Elle raconte sa journée dans son carnet, puis elle consulte l’affiche d’une croisière sur la Seine.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Lea’s diary","blocs":["We arrived in Paris on Monday. Breakfast was at eight, in the hotel garden. In the afternoon, we saw a museum near the Seine.","I love paintings, but my brother hates museums: he prefers football."],"source":"Texte écrit pour l’exercice"},{"id":"croisiere","type":"fiche","modele":"horaires","entete":"Seine river cruise","sousTitre":"Departures from the Pont Neuf","emoji":"🚤","lignes":[{"texte":"Boats leave once an hour","id":"z1"},{"texte":"Adult ticket","valeur":"€12"},{"texte":"Child ticket","valeur":"€6"},{"texte":"The trip lasts half an hour","id":"z2"}],"pied":"Enjoy the view!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre noms** employés sans article parce qu’ils désignent un repas, un sport ou une généralité (ne touche pas les noms propres).","aide":"Cherche un repas, deux pluriels pris en général, et un sport.","type":"zone","document":"carnet","multiple":true},{"enonce":"Pourquoi écrit-on « **the** Seine » ?","aide":"Pense à *the Thames*, *the Atlantic*, *the Alps*.","type":"choix","options":[{"id":"a","texte":"Les fleuves prennent l’article *the*"},{"id":"b","texte":"Parce que Seine est un nom indénombrable"},{"id":"c","texte":"Parce que la phrase est au passé"},{"id":"d","texte":"Les noms de ville prennent l’article *the*"}],"multiple":false},{"enonce":"Sur l’affiche, touche la ligne qui indique **la fréquence** des départs.","aide":"Cherche une expression construite avec *a / an*, qui veut dire « par heure ».","type":"zone","document":"croisiere","multiple":false},{"enonce":"Combien de minutes dure la croisière ?","aide":"Lis la dernière ligne : *half an hour*.","type":"nombre","unite":"min"},{"enonce":"Complète le commentaire de Léa.","aide":"Même tournure que *What a nice day!*.","type":"trous","segments":["What ",0," nice trip!"],"banque":["an","the","a","some"]}]}$ex$::jsonb,
