   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c2","i4":"c0"}},"explication":"Les personnes au singulier prennent **’s** ; un pluriel en -s prend **l’apostrophe seule** ; une chose passe par **of**. *Today’s* est une expression de temps."},{"cle":{"type":"zone","ids":["m35"]},"explication":"**girls’** : pluriel en -s, donc apostrophe seule."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"**It’s my father’s car.** L’ordre est inverse du français : possesseur + ’s + objet."},{"cle":{"type":"trous","trous":[["hers"]]},"affichage":"hers","explication":"**hers** : *it’s hers*, « il est à elle »."}]$ex$::jsonb),
