   $ex${"titre":"Les affaires oubliées","competence":"raisonner","situation":"Jack et Mia ont retrouvé des objets au club de sport. Un tableau dit à qui ils appartiennent et ils discutent par SMS.","documents":[{"id":"objets","type":"tableau","titre":"Lost property","colonnes":["Object","Owner"],"lignes":[["red phone","Jack"],["blue bag","Mia"],["green keys","Jack and Mia"],["black umbrella","Mia’s brother"]],"source":"Tableau écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Jack et Mia","participants":[{"nom":"Jack","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Jack","texte":"Is the red phone yours, Mia?"},{"qui":"Mia","texte":"No, it’s not mine. It’s his."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit **à qui est le sac bleu**.","aide":"Repère la ligne du *blue bag*, puis la colonne *Owner*.","type":"zone","document":"objets","multiple":false},{"enonce":"Mia dit que le téléphone n’est pas à elle. Touche le **pronom possessif** qui désigne Jack.","aide":"Un pronom possessif se met à la place du nom.","type":"zone","document":"sms","multiple":false},{"enonce":"Les clés vertes sont à Jack et Mia ensemble.","aide":"Quand deux personnes possèdent une même chose, on ne met la marque qu’au dernier nom.","type":"trous","segments":["These are Jack and ",0," keys."],"banque":["Mia’s","Mia is","Mia","of Mia"]},{"enonce":"Quelle phrase est correcte pour parler du sac bleu ?","aide":"Le possesseur est une personne : utilise le génitif.","type":"choix","options":[{"id":"a","texte":"It’s Mia bag."},{"id":"b","texte":"It’s Mias bag."},{"id":"c","texte":"It’s the bag of Mia."},{"id":"d","texte":"It’s Mia’s bag."}],"multiple":false},{"enonce":"Associe chaque tournure à son sens.","aide":"Le génitif sans nom désigne un lieu, *of mine* un parmi d’autres.","type":"association","gauche":[{"id":"g0","texte":"at my grandmother’s"},{"id":"g1","texte":"a friend of mine"},{"id":"g2","texte":"Tom and Kate’s house"},{"id":"g3","texte":"the roof of the house"}],"droite":[{"id":"d0","texte":"la maison de Tom et Kate (une seule)"},{"id":"d1","texte":"chez ma grand-mère"},{"id":"d2","texte":"un de mes amis"},{"id":"d3","texte":"le toit de la maison"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"**Mia** : le sac bleu appartient à Mia."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**his** : *it’s his* = « il est à lui », donc à Jack."},{"cle":{"type":"trous","trous":[["mia s"]]},"affichage":"Mia’s","explication":"**Jack and Mia’s keys** : un seul objet à deux propriétaires, donc un seul ’s à la fin."},{"cle":{"type":"choix","ids":["d"]},"explication":"**It’s Mia’s bag.** Pour une personne, on emploie ’s et non *of*."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"*At my grandmother’s* = chez elle ; *a friend of mine* = un parmi mes amis ; le double génitif = une seule maison ; *of* pour une chose."}]$ex$::jsonb),
  ('ee9faea6-63b0-58c0-a2a8-4c00cd3b1c53'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans le frigo de Ben","competence":"comprendre-langue","situation":"Sa mère veut savoir ce qu’il reste à manger. Ben regarde dans le frigo et répond par message.","documents":[{"id":"frigo","type":"dialogue","modele":"sms","titre":"Messages de Mum et Ben","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Are there any eggs in the fridge?"},{"qui":"Ben","texte":"Yes, there are some eggs, but there is no milk."},{"qui":"Mum","texte":"How much cheese do we have?"},{"qui":"Ben","texte":"A little. And a few apples."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui dit qu’il n’y a **pas du tout** de lait.","aide":"C’est un quantifieur qui équivaut à *not any*.","type":"zone","document":"frigo","multiple":false},{"enonce":"Range ces quantifieurs selon le nom qu’ils accompagnent.","aide":"Les œufs se comptent, le fromage non.","type":"categories","categories":[{"id":"c0","texte":"Avec un dénombrable"},{"id":"c1","texte":"Avec un indénombrable"}],"items":[{"id":"i0","texte":"many"},{"id":"i1","texte":"few"},{"id":"i2","texte":"little"},{"id":"i3","texte":"a little"},{"id":"i4","texte":"much"},{"id":"i5","texte":"a few"}]},{"enonce":"Complète la suite de la conversation.","aide":"Dans une phrase négative, on emploie le même mot que dans une question.","type":"trous","segments":["There is a little cheese, but there isn’t ",0," butter."],"banque":["much","some","no","any"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**no** : *there is no milk* = *there isn’t any milk*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"**many, a few, few** vont avec des noms qu’on compte (*eggs, apples*) ; **much, a little, little** avec les indénombrables (*cheese, milk*)."},{"cle":{"type":"trous","trous":[["any"]]},"affichage":"any","explication":"**any** : après *isn’t*, on utilise *any* (*there isn’t any butter*)."}]$ex$::jsonb),
  ('ee9faea6-63b0-58c0-a2a8-4c00cd3b1c53'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les résultats du sondage de la cantine","competence":"analyser-texte","situation":"Le délégué des élèves a mené un sondage sur la cantine et en résume les résultats dans le journal du collège.","documents":[{"id":"sondage","type":"texte","genre":"article","titre":"Canteen survey","blocs":["A survey of the school canteen gives these results.","Some students bring a packed lunch. Few students like the fish on Fridays.","A lot of students drink water, but not much juice is sold. There isn’t any cake left by noon."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche le quantifieur qui dit qu’**il y a trop peu** d’élèves qui aiment le poisson.","aide":"Il n’est pas précédé de *a*.","type":"zone","document":"sondage","multiple":false},{"enonce":"Quelle phrase veut dire « **quelques** élèves aiment le poulet » (ton positif) ?","aide":"L’article *a* rend la phrase positive.","type":"choix","options":[{"id":"a","texte":"Few students like the chicken."},{"id":"b","texte":"Little students like the chicken."},{"id":"c","texte":"A few students like the chicken."},{"id":"d","texte":"Much students like the chicken."}],"multiple":false},{"enonce":"Complète avec le quantifieur qui convient.","aide":"Il ne reste pas de gâteau du tout.","type":"trous","segments":["At noon there is ",0," cake left : the plates are empty."],"banque":["no","any","much","some"]},{"enonce":"Remets en ordre : « Combien d’élèves apportent un repas froid ? » La phrase commence par How.","aide":"*Students* se compte : on utilise *many*.","type":"ordre","items":[{"id":"a","texte":"bring"},{"id":"b","texte":"students"},{"id":"c","texte":"many"},{"id":"d","texte":"a packed lunch"},{"id":"e","texte":"How"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15"]},"explication":"**Few** (sans *a*) : « peu, trop peu ». Avec *a few*, on dirait « quelques-uns », sur un ton positif."},{"cle":{"type":"choix","ids":["c"]},"explication":"**A few students like the chicken.** *Few* serait négatif ; *little* et *much* ne vont pas avec un nom dénombrable."},{"cle":{"type":"trous","trous":[["no"]]},"affichage":"no","explication":"**no cake** : *no* équivaut à *not any* et s’emploie dans une phrase affirmative."},{"cle":{"type":"ordre","ids":["e","c","b","a","d"]},"explication":"**How many students bring a packed lunch?** *Many* accompagne un nom dénombrable pluriel."}]$ex$::jsonb),
